const familyPhotos={'demo-a':'demo-a','demo-b':'demo-b','demo-c':'demo-c','demo-d':'demo-d'};
const avatar=(p=P(),large=false)=>`<span class="avatar ${large?'lg':''} alt${(p.color||0)%4} ${familyPhotos[p.id]?'has-photo':''}" aria-hidden="true">${familyPhotos[p.id]?`<img src="assets/family/${familyPhotos[p.id]}.webp" alt="" width="80" height="80">`:p.id==='guest'?icon('leaf'):esc(initials(p.name))}</span>`;
const badge=(text,type='')=>`<span class="badge ${type}">${esc(text)}</span>`;
const link=(label,route,cls='btn',ic='')=>`<a class="${cls}" href="#${route}">${ic?icon(ic):''}${label}</a>`;
const button=(label,action,cls='btn',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const cardIcon=(name,sage=false)=>`<div class="card-icon ${sage?'sage':''}">${icon(name)}</div>`;
const notice=(text,type='',ic='info')=>`<div class="notice ${type}">${icon(ic)}<div>${text}</div></div>`;
const empty=(title,text,ic='chart',action='')=>`<section class="card empty-large">${cardIcon(ic,true)}<h2>${title}</h2><p>${text}</p>${action}</section>`;
function persist(message){try{localStorage.setItem(KEY,JSON.stringify(db));if(message)toast(message);return true;}catch{toast('Chưa lưu được trên trình duyệt này. Hãy xuất dữ liệu trước khi đóng trang.');return false;}}
function toast(text){const el=$('#toast');el.textContent=text;Locale.translate(el);el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3800);}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;Locale.translate($('#modal'));if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();}
function go(route){closeModal();if(location.hash==='#'+route)render();else location.hash=route;}
function route(){return decodeURIComponent(location.hash.replace(/^#\/?/,''))||'login';}
const primaryNav=[['today','Hôm nay','home'],['learn','Học','book'],['review','Ôn','review'],['notebook','Sổ học tập','note'],['discover','Khám phá','compass']];
function activeSection(r){if(['learn','course','lesson','quiz','summary','library'].includes(r.split('/')[0]))return 'learn';if(['review','kana','flash','mistakes'].includes(r))return 'review';if(r.startsWith('note')||r==='notebook')return 'notebook';if(['discover','dictionary','characters','character','achievements','assistant'].includes(r.split('/')[0]))return 'discover';return r==='today'?'today':'';}
function navMarkup(bottom=false){const active=activeSection(route());return primaryNav.map(([r,l,ic])=>`<a href="#${r}" class="${bottom?'':'navlink '}${r===active?'active':''}" ${r===active?'aria-current="page"':''} title="${l}">${icon(ic)}<span>${bottom&&r==='notebook'?'Sổ tay':l}</span></a>`).join('');}
