const moduleData=[['kana','Luyện Kana','Nhận mặt chữ, tô theo và tự viết.','pen','Bản mẫu','practice'],['flash','Flashcard','Lật thẻ và tự đánh giá điều vừa nhớ.','layers','Bản mẫu','practice'],['dictionary','Từ điển','Tra từ, cách đọc và lưu ví dụ.','search','Sáu mục mẫu','reference'],['library','Thư viện bài','Tìm nội dung theo mục tiêu và kỹ năng.','book','Khung đề xuất','study'],['characters','Nhân vật & hội thoại','Những nhân vật có quan hệ và bối cảnh liên kết.','users','Bản nháp','study'],['listening','Luyện nghe & nói','Dự kiến phát triển khi có nội dung và cơ chế kiểm chứng.','sound','Chưa phát hành','practice'],['achievements','Thành tích','Cột mốc học tập có ý nghĩa, không xếp hạng.','award','Bản mẫu','study'],['reports','Báo cáo','Xem bằng chứng từ các lượt thử của bạn.','chart','Bản mẫu','study'],['assistant','Michi · Bạn đồng hành','Gợi ý theo mục tiêu và hoạt động trong bản thử.','chat','Theo quy tắc','study']];
function titleOf(r){if(r.startsWith('admin'))return 'Xưởng nội dung';if(r.startsWith('lesson/'))return 'Bài học N5';if(r.startsWith('summary/'))return 'Tổng kết buổi học';if(r.startsWith('settings/'))return 'Không gian của tôi';if(r.startsWith('course/'))return 'Khóa học & lộ trình';if(r.startsWith('character/'))return 'Nhân vật & hội thoại';const item=screenGroups.flatMap(g=>g.items).find(i=>i[0]===r);return item?.[1]||'Nihongo Path';}
function brandMarkup(){return `<img class="brand-symbol" src="assets/n-mark.svg" width="44" height="44" alt="Nihongo Path · N"><span class="brand-copy" data-no-translate><strong>Nihongo</strong><strong>Path<span class="brand-dot">.</span></strong></span>`;}
function shell(content){return `<aside class="sidebar"><a href="#today" class="brand" aria-label="Nihongo Path — Hôm nay">${brandMarkup()}</a><div class="nav-caption">HỌC MỖI NGÀY</div><nav class="mainnav" aria-label="Điều hướng chính">${navMarkup()}</nav><div class="sidebar-moment" aria-hidden="true"><span class="moment-jp">一歩ずつ。</span><p>Mỗi ngày,<br>một bước tiến.</p><span class="moment-line"></span></div><div class="side-bottom"><a class="navlink" href="#reports" title="Báo cáo">${icon('chart')}<span>Báo cáo</span></a><a class="navlink" href="#guide" title="Hướng dẫn">${icon('help')}<span>Hướng dẫn</span></a></div></aside><div class="shell"><header class="topbar"><button class="iconbutton menu-toggle" data-action="quicknav" aria-label="Mở danh sách trang">${icon('map')}</button><a class="mobile-brand" href="#today" aria-label="Nihongo Path — Hôm nay">${brandMarkup()}</a><div class="breadcrumb">${icon('home')}<span>Không gian học</span><span>/</span><b>${esc(titleOf(route()))}</b></div><div class="top-actions"><a href="#library" class="search-short">${icon('search')}<span>Tìm bài học, chủ đề…</span></a>${Locale.switcher()}<a href="#settings/goals" class="iconbutton" aria-label="Không gian của tôi" title="Không gian của tôi">${icon('gear')}</a><button class="profile-button" data-action="profilemenu" aria-label="Tài khoản ${esc(P().name)}">${avatar()}<strong class="profile-name" data-no-translate>${esc(P().name)}</strong>${icon('down')}</button></div></header><main id="main" tabindex="-1">${content}<footer class="footnote"><span>NIHONGO PATH <span class="desktop-only">· Học theo cách của bạn</span></span><a href="#map">Toàn bộ trang & flow ${icon('arrow')}</a></footer></main></div><nav class="bottomnav" aria-label="Điều hướng mobile">${navMarkup(true)}</nav>`;}
function heading(title,subtitle='',eyebrow='',action=''){return `<header class="pagehead"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${action?`<div class="actions">${action}</div>`:''}</header>`;}
function mapPage(){const count=screenGroups.reduce((n,g)=>n+g.items.length,0);return `<section class="maphero"><div class="eyebrow">BẢN REVIEW TƯƠNG TÁC · 06</div><h1>Cùng một thiết kế.<br>Toàn bộ hành trình học.</h1><p>Mở từng màn hình hoặc đi theo flow. Hồ sơ, mục tiêu và lối tắt đều có thể thay đổi trong bản thử.</p><div class="actions">${link('Bắt đầu flow','login','btn primary','play')}${link('Xem dashboard','today','btn','home')}</div><span class="map-number">${count}</span></section>${notice('<strong>Bản prototype để review.</strong> Chưa có xác thực, database hay đồng bộ. Dữ liệu bạn thao tác chỉ lưu thử trên trình duyệt này. Không nhập thông tin nhạy cảm.','neutral')}<div class="flowline">${[['1','Home–Login','login'],['2','Không gian của tôi','settings/goals'],['3','Hôm nay','today'],['4','Học bài mẫu','lesson'],['5','Lưu & xem lại','notebook']].map(([n,l,r])=>`<a class="flow-step" href="#${r}"><span class="step-number">${n}</span><div><strong>${l}</strong><small>Mở màn hình ${icon('arrow')}</small></div></a>`).join('')}</div><div class="inline spread wrap"><span class="small">${count} màn hình / nhóm cấu hình chính · 24 hồ sơ nhân vật nháp</span><button class="textlink" data-action="resetdemo">Đặt lại dữ liệu thử</button></div>${screenGroups.map(g=>`<section class="mapgroup"><h2>${g.title}</h2><div class="grid three">${g.items.map(([r,l,d,ic])=>`<a class="screenlink" href="#${r}">${cardIcon(ic)}<div><strong>${l}</strong><small>${d}</small></div>${icon('chevron')}</a>`).join('')}</div></section>`).join('')}`;}
function authTop(){return `<div class="auth-top"><a href="#login" class="brand" aria-label="Nihongo Path">${brandMarkup()}</a><div class="auth-top-actions"><a href="#guide" class="textlink auth-guide">Hướng dẫn</a>${Locale.switcher()}</div></div>`;}
let loginSelected='';
function loginPerson(){return db.profiles.find(p=>p.id===(loginSelected||db.demoLoginProfile)&&!p.archived)||db.profiles.find(p=>!p.archived&&p.role!=='guest')||P();}
function loginPage(){
 const people=db.profiles.filter(p=>!p.archived&&p.role!=='guest').slice(0,4),selected=loginSelected==='guest'?{id:'guest',name:'Khách',goal:'',minutes:0,role:'guest'}:loginPerson(),guest=selected.id==='guest';
 const guestCard={id:'guest',name:'Khách',color:1};
 const html = `<section class="atelier-home"><header class="atelier-header"><a href="#login" class="brand home-brand" aria-label="Nihongo Path">${brandMarkup()}<span class="brand-edition" data-no-translate>FAMILY ATELIER</span></a><div class="atelier-header-actions"><a class="home-guide" href="#guide">Hướng dẫn</a>${Locale.switcher()}</div></header><main id="main" class="atelier-main" tabindex="-1"><section class="atelier-story"><div class="atelier-kicker"><span></span> KHÔNG GIAN HỌC TIẾNG NHẬT CỦA GIA ĐÌNH</div><h1><span>Mỗi người một</span> <em>nhịp học.</em></h1><p class="atelier-intro">Một khoảng riêng để học.<br>Một hành trình để cùng nhau lớn lên.</p><div class="atelier-art" aria-hidden="true"><div class="art-disc"></div><span class="art-kanji" lang="ja">一歩</span><svg class="art-landscape" viewBox="0 0 500 180" fill="none"><path d="M0 157C80 146 119 169 182 146C233 129 239 68 281 33C317 76 341 128 389 142C433 151 464 146 500 153" stroke="currentColor" stroke-width=".8"/><path d="M249 70L271 75L280 64L293 78L310 75M0 171C110 156 182 182 260 158C327 138 428 173 500 165" stroke="currentColor" stroke-width=".65"/><circle cx="371" cy="39" r="16" fill="currentColor" opacity=".3"/></svg><div class="art-caption"><span data-no-translate>IPPŌ · 一歩</span><span>Từng bước, mỗi ngày.</span></div></div><div class="atelier-values"><span>${icon('compass')} Lộ trình riêng</span><span>${icon('review')} Ôn tập có nhịp</span><span>${icon('note')} Giữ điều đã học</span></div></section><section class="atelier-access"><div class="access-heading"><span class="atelier-kicker">CHÀO MỪNG TRỞ LẠI</span><h2>Hôm nay, ai sẽ học?</h2><p>Chọn không gian của bạn để tiếp tục.</p></div><form data-form="demologin" autocomplete="off" class="atelier-login"><input type="hidden" name="learner" value="${esc(selected.id)}"><div class="family-picker" role="group" aria-label="Chọn người học">${[...people,guestCard].map(p=>`<button type="button" class="family-choice ${p.id===selected.id?'selected':''}" data-action="loginprofile" data-id="${esc(p.id)}" aria-pressed="${p.id===selected.id}" aria-label="${esc(p.name)}"><span class="family-photo">${avatar(p,true)}<span class="family-tick">${icon('check')}</span></span><span class="family-name" ${p.id==='guest'?'':'data-no-translate'}>${esc(p.name)}</span></button>`).join('')}</div><div class="selected-learner"><span class="selected-dot"></span><strong data-no-translate>${guest?'':esc(selected.name)}</strong><span class="selected-detail">${guest?'Trải nghiệm tự do, không cần mã.':`${esc(selected.goal)} · ${selected.minutes} phút mỗi buổi`}</span></div><div class="atelier-code-area ${guest?'guest-access':''}"><label for="demo-access-code">Mã truy cập</label><div class="atelier-code-field"><input id="demo-access-code" name="demoCode" type="password" autocomplete="off" placeholder="Nhập mã của bạn" ${guest?'disabled':'required'} aria-describedby="demo-code-help login-error" ${accessError?'aria-invalid="true"':''}><button type="button" class="secret-toggle" data-action="togglecode" aria-label="Hiện mã demo" ${guest?'disabled':''}>${icon('eye')}</button></div><div class="atelier-code-help" id="demo-code-help"><span>Mã thử: <code data-no-translate>PATH-DEMO</code></span>${button('Điền mã','fillcode','textlink')}</div></div><div class="guest-message" ${guest?'':'hidden'}>${icon('leaf')} Bạn có thể xem bài mẫu trước khi tạo hồ sơ.</div><div class="atelier-form-options">${guest?'<span class="guest-options-note">Có thể đổi sang hồ sơ gia đình bất cứ lúc nào.</span>':`<label class="check-inline"><input name="rememberProfile" type="checkbox" ${rememberDemoProfile?'checked':''}>Nhớ lựa chọn của tôi</label><a href="#forgot">Quên mã?</a>`}</div><p id="login-error" class="atelier-error" role="alert">${esc(accessError)}</p><button class="atelier-enter" type="submit"><span>${guest?'Vào học thử':'Vào không gian học'}</span>${icon('arrow')}</button><p class="atelier-demo-note">${guest?'Bản trải nghiệm · Dữ liệu lưu trên thiết bị.':'Bản trải nghiệm · Chỉ dùng mã mẫu.'}</p></form><div class="atelier-access-links"><a href="#invite">Tôi có mã mời ${icon('arrow')}</a><a href="#profiles">Hồ sơ khác ${icon('users')}</a></div></section></main><footer class="atelier-footer"><span class="footer-philosophy"><span lang="ja" data-no-translate>自分のペースで、一歩ずつ。</span><span>Học theo nhịp của bạn.</span></span><span class="footer-access-note">Dữ liệu thử lưu trên thiết bị · Chưa có xác thực thật</span><a href="#map">Toàn bộ trang ${icon('arrow')}</a></footer></section>`;
 return NPLogin.enhance(html,people,selected);
}
function profilesPage(){return `<section class="auth-shell access-shell">${authTop()}<main id="main" class="auth-main" tabindex="-1"><div class="auth-centered">${accessSteps(2)}${heading('Hôm nay ai học?','Chọn hồ sơ để tiếp tục. Mục tiêu và cách học của mỗi người được giữ riêng.','CHỌN NGƯỜI HỌC')}${notice('Danh sách dưới đây là hồ sơ mẫu. Chọn avatar chưa phải là xác thực tài khoản thật.','neutral')}<div class="profile-grid">${db.profiles.filter(p=>!p.archived).map(p=>`<button class="profile-tile ${p.id===P().id?'profile-current':''}" data-action="selectprofile" data-id="${esc(p.id)}">${avatar(p,true)}<div><strong data-no-translate>${esc(p.name)}</strong><small>Mục tiêu: ${esc(p.goal)} · ${p.minutes} phút</small><span class="profile-continue">${p.onboarded?'Tiếp tục học':'Thiết lập ban đầu'} ${icon('arrow')}</span></div>${badge(p.role==='manager'?'Quản lý gia đình mẫu':'Học viên mẫu','sage')}${icon('chevron')}</button>`).join('')}</div><div class="actions access-bottom-actions">${link('Thêm người học qua mã mời','invite','btn','plus')}${link('Quay lại Login','login','btn ghost','back')}</div></div></main><footer class="access-footer"><span>Dữ liệu thử chỉ lưu trên trình duyệt này.</span>${link('Sơ đồ trang','map','textlink','map')}</footer></section>`;}
function onboardingPage(){return accessPage('Bắt đầu từ điều phù hợp.','Chỉ cần ba lựa chọn. Bạn có thể đổi sau trong Không gian của tôi.',`<form data-form="onboarding" class="access-onboarding"><label>Tên hiển thị<input name="name" required maxlength="60" value="${esc(P().name)}"></label><label>Mục tiêu hiện tại<select name="goal">${goalOptions(P().goal)}</select><span class="form-help">Mục tiêu mong muốn, chưa phải trình độ được xác nhận.</span></label><label>Thời gian mỗi buổi<select name="minutes">${minuteOptions(P().minutes)}</select></label>${notice('Bài học hiện có là nội dung mẫu. Các khóa đầy đủ N5–N1 chưa phát hành.','neutral')}<button class="btn primary wide section" type="submit">Lưu & tiếp tục ${icon('arrow')}</button>${link('Thiết lập sau','ready','textlink')}</form>`,3,'compass');}
function todayPage(){const p=P(),started=p.resume;const available=['N5','Nền tảng','Giao tiếp hằng ngày'].includes(p.goal);const mins=p.todayMinutes||p.minutes;const first=Math.max(2,Math.round(mins/4)),second=mins-first;return `<header class="pagehead today-head"><div><div class="eyebrow today-eyebrow">KHÔNG GIAN HỌC CỦA BẠN</div><div class="greeting">Chào ${esc(p.name)},</div><h1>Hôm nay học gì?</h1><a class="goal" href="#settings/goals">${icon('compass')} Mục tiêu: ${esc(p.goal)} ${icon('pen')}</a><p class="small">Mục tiêu và nhịp học có thể thay đổi.</p></div><div class="time-selector"><span class="small">Hôm nay bạn có</span><div class="chiprow">${[10,20,30].map(m=>button(icon('clock')+` ${m} phút`,'minutes',`chip ${mins===m?'active':''}`,`data-minutes="${m}" aria-pressed="${mins===m}"`)).join('')}</div></div></header>${!available?notice(`<strong>Mục tiêu ${esc(p.goal)} của bạn được giữ nguyên.</strong> Khóa tương ứng chưa phát hành. Dưới đây là flow bài mẫu N5 để xem giao diện, không phải đánh giá trình độ hoặc yêu cầu học lại.`,'neutral'):''}<div class="columns ${!available?'section':''}"><section class="card plan"><span class="plan-watermark" aria-hidden="true">あ</span><div class="cardhead"><h2>${icon('leaf')} ${started?'Tiếp tục bài mẫu':available?'Kế hoạch gợi ý':'Flow bài mẫu tham khảo'}</h2><span class="small">${mins} phút · dự kiến</span></div><ol class="plan-steps"><li class="plan-step"><span class="step-number">1</span><div class="step-copy"><strong>Ôn nhận diện Kana</strong><p>Làm quen cách nhận mặt chữ</p></div><span class="duration">${first} phút</span></li><li class="plan-step"><span class="step-number">2</span><div class="step-copy"><strong>N5 · Giới thiệu bản thân</strong><p>Học mẫu câu và luyện tập ngắn</p></div><span class="duration">${second} phút</span></li></ol>${link(started?'Tiếp tục bài đang thử':'Xem bài mẫu','lesson','btn primary wide startbutton','play')}<div class="underbutton"><span>${available?'Gợi ý ban đầu theo mục tiêu · nội dung mẫu':'Minh họa N5 · không thay đổi mục tiêu'}</span><a class="textlink" href="#settings/goals">Điều chỉnh ${icon('arrow')}</a></div></section><div class="stack today-side">${michiCard('Bạn có thể thử một bài mẫu trước, rồi chọn nhịp học phù hợp.')}<section class="card empty">${cardIcon('chart')}<div><h3>Tiến bộ của bạn</h3><p>${p.attempts.length?p.attempts.length+' lượt kiểm tra thử đã ghi nhận.':'Chưa có kết quả để đánh giá.'}</p>${link('Xem báo cáo','reports','textlink','arrow')}</div></section></div></div><section class="section"><div class="section-title"><h2>Lối tắt của tôi</h2>${button(icon('pin')+' Chỉnh lối tắt','shortcuts','textlink')}</div><div class="grid three shortcut-grid">${p.shortcuts.map(id=>{const m=moduleData.find(m=>m[0]===id)||[id,'Sổ học tập','Ghi lại điều cần nhớ.','note','Bản mẫu'];return `<a class="shortcut" href="#${esc(id)}">${cardIcon(m[3])}<div><strong>${m[1]}</strong><small>${m[2]}</small>${badge(m[4])}</div>${icon('chevron','chev')}</a>`;}).join('')}</div></section><section class="section card empty">${cardIcon('calendar',true)}<div><h3>Chưa có lịch ôn tự động</h3><p>Lịch ôn giãn cách chưa triển khai. Bạn có thể luyện thẻ mẫu hoặc xem các lỗi trong lượt thử.</p>${link('Mở trung tâm ôn','review','textlink','arrow')}</div></section><div class="section inline spread wrap"><span class="small">Học theo mục tiêu của bạn, với dữ liệu của bạn.</span>${link('Khám phá lộ trình','learn','textlink','arrow')}</div>`;}
function michiCard(text){return `<section class="card michi-card"><h2>Michi gợi ý</h2><p class="michi-text">${text}</p>${link('Vì sao có gợi ý này?','assistant','textlink','help')}<img class="michi-image" src="assets/michi.png" alt="Michi, bạn đồng hành"></section>`;}
function foundationStudioCard(){return `<section class="card section" aria-label="Phòng luyện viết Kana"><span class="eyebrow">FOUNDATION · KANA WRITING STUDIO</span><h2>Nghe âm, xem từng nét, rồi tự viết.</h2><p>Chọn Hiragana hoặc Katakana, nghe cách đọc, xem đúng thứ tự nét và luyện trên bảng viết. Lượt tự luyện được ghi nhận riêng, không coi là chấm đúng nét hay đã thuộc chữ.</p><div class="actions">${link('Mở phòng luyện viết','kana','btn primary','pen')}</div></section>`;}
function learnPage(){return `${heading('Hành trình của bạn, từng bước.','Chọn lộ trình theo mục tiêu. Các khóa chưa phát hành được phân biệt rõ.','HỌC')}<div class="notice neutral">${icon('compass')}<div><strong>Mục tiêu hiện tại: ${esc(P().goal)}</strong><br>Không thay đổi kết quả đã ghi nhận khi bạn chọn mục tiêu mới. ${link('Chỉnh mục tiêu','settings/goals','textlink')}</div></div><div class="grid three section">${courses.map(([id,l,d,s])=>`<article class="card course-card"><div class="course-level">${l}</div>${badge(s,['foundation','N5'].includes(id)?'sage':'muted')}<p>${d}</p>${link(['foundation','N5'].includes(id)?'Xem lộ trình mẫu':'Xem khung đề xuất','course/'+id,'btn','arrow')}</article>`).join('')}</div>${foundationStudioCard()}<div class="section">${link('Tìm bài trong thư viện','library','textlink','search')}</div>`;}
function coursePage(id){const c=courses.find(c=>c[0]===id);if(!c)return notFound();const available=['foundation','N5'].includes(id);const proposed=id==='foundation'?['Nhận diện Hiragana & Katakana','Âm đục, âm bán đục và âm ghép','Luyện viết & phản xạ nhận mặt chữ','Kiểm tra nền tảng']:id==='N5'?['Giới thiệu bản thân','Con người, đồ vật và địa điểm','Hoạt động hằng ngày','Ôn tập theo tình huống']:['Từ vựng & Kanji trong ngữ cảnh','Ngữ pháp gắn với tình huống','Đọc hiểu & nghe hiểu','Ôn tập và kiểm tra theo kỹ năng'];return `${link('Tất cả khóa học','learn','textlink','back')}${heading(c[1]==='Nền tảng'?'Xây nền tảng vững, học tiếp dễ hơn.':'Lộ trình '+c[1],c[2],available?'KHUNG LỘ TRÌNH MẪU':'KHUNG ĐỀ XUẤT · CHƯA PHÁT HÀNH',badge(c[3],available?'sage':'muted'))}<div class="columns"><section class="card"><h2>Các chặng học</h2>${proposed.map((t,i)=>`<div class="lessonrow"><span class="step-number">${i+1}</span><div class="lesson-copy"><strong>${t}</strong><p>${available&&i===0?'Có phần minh họa để xem flow.':'Nội dung chi tiết sẽ được biên soạn và review riêng.'}</p></div>${available&&i===0?link('Mở bản mẫu',id==='foundation'?'kana':'lesson','btn sm','arrow'):badge('Chưa phát hành','muted')}</div>`).join('')}</section><div class="stack">${notice('<strong>Mục tiêu không phải chứng nhận trình độ.</strong> Khung này chưa đại diện cho một khóa học hoàn chỉnh.')}<section class="card"><h2>Cách sử dụng</h2><p>Chọn đúng chặng bạn cần. Phần đã học sẽ được giữ khi đổi lộ trình.</p><div class="section">${link('Cấu hình khóa đang theo','settings/goals','btn wide')}</div></section></div></div>`;}
const lessonSteps=[{label:'Mẫu câu',title:'Nói một điều về bản thân.',body:'Mẫu câu đơn giản để nói mình là ai hoặc làm công việc gì.',jp:'わたしは<ruby>学生<rt>がくせい</rt></ruby>です。',meaning:'Tôi là học sinh / sinh viên.',tip:'は nêu chủ đề của câu. Trong vai trò trợ từ ở đây, は được đọc là わ (wa).'}, {label:'Từ vựng',title:'Đặt từ vào một câu có nghĩa.',body:'Thay danh từ để nói về người hoặc vai trò khác.',jp:'田中さんは<ruby>先生<rt>せんせい</rt></ruby>です。',meaning:'Anh/chị Tanaka là giáo viên.',tip:'先生（せんせい）là cách gọi thầy/cô và một số người hành nghề chuyên môn. Trong bài mẫu này dùng nghĩa giáo viên.'}, {label:'Tự thử',title:'Thử nói câu của riêng bạn.',body:'Bạn có thể giới thiệu mình bằng tên hoặc một vai trò phù hợp.',jp:'わたしは＿＿です。',meaning:'Tôi là ____.',tip:'Nội dung này là bài minh họa ngắn do ứng dụng biên soạn cho prototype; chưa phải toàn bộ Bài 1 của giáo trình.'}];
function legacyLessonPage(){const s=lessonSteps[lessonStep];return `<div class="reader">${link('Khóa N5','course/N5','textlink','back')}${heading('Giới thiệu bản thân','Bài mẫu ngắn · Không có âm thanh trong bản này.','N5 · BÀI MINH HỌA')}<div class="lesson-tabs">${lessonSteps.map((s,i)=>button(`${i+1}. ${s.label}`,'lessonstep',`chip ${i===lessonStep?'active':''}`,`data-step="${i}"`)).join('')}</div><article class="card lesson-stage"><div class="inline spread"><span class="small">Bước ${lessonStep+1} / ${lessonSteps.length}</span>${badge('Nội dung mẫu','sage')}</div><div class="progress-line"><span style="width:${(lessonStep+1)/3*100}%"></span></div><h2>${s.title}</h2><p class="muted">${s.body}</p><div class="example"><div class="jp">${s.jp}</div><p>${s.meaning}</p></div>${notice(s.tip,'neutral')}<div class="actions section">${button(icon('note')+' Lưu câu vào sổ','savelesson','btn')}${button(icon('sound')+' Chưa có bản thu','noaudio','btn ghost')}</div><div class="divider"></div><div class="actions">${lessonStep>0?button(icon('back')+' Trước','lessonprev','btn'):''}${lessonStep<2?button('Tiếp theo '+icon('arrow'),'lessonnext','btn primary right'):link('Luyện tập ngắn','quiz','btn primary right','arrow')}</div></article><p class="article-note">Gợi ý: đọc câu, ẩn cách đọc nếu cần thử sức, rồi tự thay thông tin của bạn. ${link('Chỉnh cách hiển thị','settings/learning','textlink')}</p></div>`;}
const questions=[{q:'学生 có cách đọc nào?',options:['せんせい','がくせい','ほん'],correct:1,hint:'Từ này bắt đầu bằng がく.',explanation:'学生 đọc là がくせい, nghĩa là học sinh hoặc sinh viên.'},{q:'Trong câu わたしは学生です。, は được đọc thế nào?',options:['ha','wa','ho'],correct:1,hint:'Ở đây は làm trợ từ nêu chủ đề.',explanation:'Khi làm trợ từ nêu chủ đề, は được đọc là わ (wa). Chữ は đứng riêng trong bảng Kana được đọc ha.'},{q:'先生 có nghĩa nào trong bài mẫu?',options:['Giáo viên','Quyển sách','Nhật Bản'],correct:0,hint:'Đây là người giúp học viên học bài.',explanation:'先生（せんせい）trong bài mẫu được dùng với nghĩa giáo viên.'}];
function legacyQuizPage(){const q=questions[quizIndex];return `<div class="reader">${link('Quay lại bài học','lesson','textlink','back')}${heading('Thử nhớ lại, không cần vội.','Ba câu để xem flow luyện tập và phản hồi.','KIỂM TRA MẪU')}<section class="card lesson-stage"><div class="inline spread"><span class="small">Câu ${quizIndex+1} / ${questions.length}</span>${badge('Kết quả chỉ của lượt thử này','outline')}</div><div class="progress-line"><span style="width:${quizIndex/3*100}%"></span></div><h2>${q.q}</h2><div class="options">${q.options.map((o,i)=>`<button class="answer-option ${quizSelected===i?'selected':''} ${quizChecked&&i===q.correct?'correct':''} ${quizChecked&&quizSelected===i&&i!==q.correct?'incorrect':''}" data-action="quizselect" data-index="${i}" ${quizChecked?'disabled':''}><span class="option-letter">${'ABC'[i]}</span>${esc(o)}</button>`).join('')}</div>${quizHints[quizIndex]?notice(q.hint,'lavender'):quizChecked?'':button(icon('help')+' Cần một gợi ý?','quizhint','textlink')}${quizChecked?`<div class="feedback ${quizSelected===q.correct?'':'bad'}"><strong>${quizSelected===q.correct?'Đúng ở câu này.':'Cùng xem lại.'}</strong><p>${q.explanation}</p>${quizHints[quizIndex]?'<p class="small">Lượt này có dùng gợi ý.</p>':''}</div>`:''}<div class="actions section">${quizChecked?button(quizIndex===2?'Xem tổng kết '+icon('arrow'):'Câu tiếp theo '+icon('arrow'),'quiznext','btn primary wide'):button('Kiểm tra câu trả lời','quizcheck','btn primary wide',quizSelected===null?'disabled':'')}</div></section></div>`;}
function legacySummaryPage(){const a=P().attempts.at(-1);if(!a)return heading('Tổng kết buổi học','Kết quả sẽ xuất hiện sau khi bạn hoàn tất bài kiểm tra mẫu.','TỔNG KẾT')+empty('Chưa có lượt kiểm tra mẫu','Không hiển thị điểm hoặc thời gian khi chưa có hoạt động.', 'check',link('Làm thử ba câu','quiz','btn primary','arrow'));return `<div class="reader">${heading('Một bước nhỏ đã được ghi lại.','Tổng kết lượt thử gần nhất trên trình duyệt này.','TỔNG KẾT BÀI MẪU')}<div class="review-summary">${icon('check')}<strong>${a.correct} / ${questions.length}</strong><span>Câu đúng trong bài mẫu<br><small>${a.hints} câu có gợi ý · chưa đánh giá trình độ tổng thể</small></span></div><div class="card"><h2>Điều bạn vừa luyện</h2><div class="checklist">${questions.map((q,i)=>`<div>${icon(a.answers[i]===q.correct?'check':'review')}<span>${q.explanation}</span></div>`).join('')}</div><div class="divider"></div><h3>Bước tiếp theo</h3><p class="small">${a.correct<3?'Xem lại câu chưa đúng, rồi thử dùng mẫu câu với thông tin của bạn.':'Thử đặt một câu của riêng bạn. Trả lời đúng một lần chưa khẳng định đã nhớ lâu.'}</p><div class="actions section">${button('Lưu tổng kết vào sổ','savesummary','btn primary','')}${link('Xem lỗi cần ôn','mistakes','btn')}${link('Về Hôm nay','today','btn ghost')}</div></div></div>`;}
function legacyReviewPage(){const mistakes=getMistakes();return `${heading('Ôn điều cần ôn, vừa đủ hôm nay.','Chọn một hoạt động hoặc xem lại câu trả lời của bài mẫu.','ÔN TẬP')}<div class="notice neutral">${icon('calendar')}<div><strong>Chưa có lịch ôn giãn cách tự động.</strong><br>Bản thử ghi nhận lượt kiểm tra, viết và tự đánh giá thẻ; chưa xếp lịch ôn như một hệ thống hoàn chỉnh.</div></div><div class="grid three section">${[['kana','Luyện viết Kana','Tô theo hoặc tự viết; chưa chấm thứ tự và độ đúng của nét.','pen'],['flash','Flashcard','Sáu thẻ mẫu để lật, tự đánh giá và lưu vào sổ.','layers'],['mistakes','Lỗi cần ôn',mistakes.length?mistakes.length+' câu cần xem lại từ lượt kiểm tra gần nhất.':'Làm bài kiểm tra mẫu để có câu cần xem lại.','help']].map(([r,t,d,i])=>`<section class="card module-card">${cardIcon(i)}${badge('Bản mẫu','sage')}<h2>${t}</h2><p>${d}</p>${link('Mở hoạt động',r,'btn','arrow')}</section>`).join('')}</div><section class="section">${michiCard('Nếu chưa có lịch sử học, hãy thử một hoạt động ngắn. Mình chưa kết luận bạn yếu phần nào.')}</section>`;}
const hira=[...'あいうえおかきくけこさしすせそたちつてとなにぬねのはひふへほまみむめもやゆよらりるれろわをん'];
const kata=[...'アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン'];
const roma='a i u e o ka ki ku ke ko sa shi su se so ta chi tsu te to na ni nu ne no ha hi fu he ho ma mi mu me mo ya yu yo ra ri ru re ro wa wo n'.split(' ');
function kanaPage(){const arr=kanaSet==='hira'?hira:kata;if(!arr.includes(kana))kana=arr[25];const r=roma[arr.indexOf(kana)];return `${heading('Viết chậm để nhớ lâu.','Vùng viết dùng được. Chưa có hoạt ảnh nét chuẩn hoặc chấm độ chính xác.','LUYỆN KANA',badge('Tự luyện · Bản mẫu','sage'))}<div class="kana-layout"><section class="card kana-picker"><div class="chiprow">${button('Hiragana','kanaset',`chip ${kanaSet==='hira'?'active':''}`,`data-set="hira"`)}${button('Katakana','kanaset',`chip ${kanaSet==='kata'?'active':''}`,`data-set="kata"`)}</div><div class="kanagrid" aria-label="Chọn chữ Kana">${arr.map(ch=>button(ch,'kanachar',`kanakey ${ch===kana?'selected':''}`,`data-char="${ch}" aria-pressed="${ch===kana}"`)).join('')}</div><div class="divider"></div><span class="small">Chọn một chữ để bắt đầu.<br>${arr.length} chữ cơ bản trong bảng mẫu.</span></section><section class="card writing-card"><div class="writing-head"><span class="jp">${kana}</span><span><strong>${r}</strong><br><small>${kanaSet==='hira'?'Hiragana':'Katakana'}</small></span></div><div class="mode-tabs">${[['trace','Tô theo'],['free','Tự viết']].map(([id,l])=>button(l,'writemode',writeMode===id?'active':'',`data-mode="${id}"`)).join('')}</div><div class="writing-pad"><div class="writing-glyph" ${showGlyph&&writeMode==='trace'?'':'hidden'}>${kana}</div><canvas id="writing" aria-label="Vùng luyện viết chữ ${kana}"></canvas></div><div class="writing-controls">${button(icon('undo')+' Hoàn tác','writingundo','btn')}${button(icon('trash')+' Xóa','writingclear','btn')}${button(icon('eye')+(showGlyph?' Ẩn mẫu':' Hiện mẫu'),'writingguide','btn')}</div>${button(icon('save')+' Lưu lượt luyện','savewriting','btn primary wide')}<p class="small" style="text-align:center">Tự luyện · Chưa chấm độ chính xác</p></section><aside class="stack kana-help"><section class="card"><h2>Mỗi lần một bước</h2><ol class="instructions"><li>Quan sát hình dạng chữ.</li><li>Tô chậm để làm quen.</li><li>Ẩn mẫu và tự thử lại.</li></ol><p class="small">Mẫu chỉ là hình chữ. Hướng dẫn thứ tự nét chuẩn sẽ được bổ sung sau.</p></section>${michiCard('Thử viết lại khi ẩn mẫu. Bạn có thể ghi điều cần nhớ vào sổ của mình.')}${link('Mở sổ học tập','notebook','btn','note')}</aside></div>`;}
function flashPage(){const w=words[flashIndex];return `<div class="reader">${heading('Nhớ lại trước, rồi lật thẻ.','Bộ sáu thẻ minh họa. Tự đánh giá chưa được coi là kết quả kiểm tra.','FLASHCARD')}<div class="inline spread"><span class="small">Thẻ ${flashIndex+1} / ${words.length}</span>${badge('Bản mẫu','sage')}</div><button class="card flashcard wide section" style="width:100%;color:var(--text)" data-action="flipflash" aria-label="${flashFlipped?'Lật về mặt từ':'Lật để xem nghĩa'}"><span class="small">${flashFlipped?'CÁCH ĐỌC & NGHĨA':'THỬ NHỚ CÁCH ĐỌC VÀ NGHĨA'}</span><span class="jp">${w.word}</span>${flashFlipped?`<span class="reading">${w.reading}</span>${P().prefs.romaji?`<span class="small">${w.romaji}</span>`:''}<span>${w.meaning}</span>`:'<span class="small">Chạm để lật thẻ</span>'}</button><div class="ratings">${[['again','Cần ôn lại'],['hard','Còn phân vân'],['remember','Tự thấy đã nhớ']].map(([id,l])=>button(l,'rateflash','btn',`data-rating="${id}" ${flashFlipped?'':'disabled'}`)).join('')}</div><div class="actions section">${button(icon('note')+' Lưu từ vào sổ','saveflash','btn')}${button('Thẻ khác '+icon('arrow'),'nextflash','btn ghost right')}</div><p class="article-note">Chưa có lịch ôn tự động, phát âm hoặc kiểm tra trí nhớ sau thời gian giãn cách. Các nút chỉ ghi lại tự đánh giá trong bản thử.</p></div>`;}
function getMistakes(){const a=P().attempts.at(-1);return a?questions.map((q,i)=>({...q,index:i,chosen:a.answers[i]})).filter(q=>q.chosen!==q.correct):[];}
function legacyMistakesPage(){const ms=getMistakes();return `${heading('Lỗi sai là chỗ để học tiếp.','Chỉ lấy từ lượt kiểm tra mẫu gần nhất của hồ sơ này.','LỖI CẦN ÔN')}${ms.length?`<div class="stack">${ms.map(m=>`<article class="card"><div class="inline spread"><h2>Câu ${m.index+1}</h2>${badge('Cần xem lại','amber')}</div><p>${m.q}</p><p class="small">Bạn đã chọn: ${esc(m.options[m.chosen])}</p><div class="feedback">${m.explanation}</div>${button('Lưu điều cần nhớ','savemistake','textlink',`data-index="${m.index}"`)}</article>`).join('')}</div><div class="section">${button('Làm lại bài mẫu','restartquiz','btn primary')}</div>`:empty('Chưa có lỗi cần ôn',P().attempts.length?'Lượt mẫu gần nhất không có câu sai. Chưa thể kết luận đã nhớ bền.':'Bạn chưa hoàn thành bài kiểm tra mẫu. Không có dữ liệu để suy đoán điểm yếu.','check',link('Mở kiểm tra mẫu','quiz','btn primary','arrow'))}`;}
let noteQuery='',dictionaryQuery='',libraryQuery='',characterQuery='';
const noteTypes={note:'Ghi chú',word:'Từ vựng',sentence:'Câu đã lưu',exercise:'Bài tập',mistake:'Lỗi cần ôn',summary:'Tổng kết',next:'Bước tiếp theo'};
function normalize(s){return s.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');}
function noteList(){const ns=P().notes.filter(n=>(noteFilter==='all'||n.type===noteFilter)&&normalize(n.title+' '+n.body+' '+n.source).includes(normalize(noteQuery)));return ns.length?`<div class="grid two">${ns.map(n=>`<article class="card notecard"><div class="note-meta">${badge(noteTypes[n.type]||'Ghi chú','sage')}<small>${new Date(n.at).toLocaleDateString('vi-VN')}</small></div><h3 data-no-translate>${esc(n.title)}</h3><p class="note-body" data-no-translate>${esc(n.body)}</p><small><span>Nguồn:</span> <span data-no-translate>${esc(n.source||'Học viên tự viết')}</span></small><div class="actions">${n.target?link('Quay lại luyện',n.target,'textlink','arrow'):''}${button('Sửa','editnote','textlink',`data-id="${esc(n.id)}"`)}${button('Xóa bản thử','deletenote','textlink right',`data-id="${esc(n.id)}"`)}</div></article>`).join('')}</div>`:empty('Một nơi để giữ điều đáng nhớ.','Lưu từ trong flashcard, câu trong bài học hoặc viết ghi chú của riêng bạn. Dữ liệu tách theo hồ sơ trên trình duyệt này.','note',button('Thêm ghi chú đầu tiên','newnote','btn primary'));}
function notebookPage(){return `${heading('Sổ học tập của '+esc(P().name),'Ghi chú, bài tập, từ và câu đã lưu cùng nằm ở đây, với nguồn riêng.','SỔ HỌC TẬP',button(icon('plus')+' Thêm ghi chú','newnote','btn primary'))}<div class="toolbar"><div class="searchbox">${icon('search')}<input id="note-search" value="${esc(noteQuery)}" placeholder="Tìm trong sổ của bạn…" aria-label="Tìm ghi chú"></div><select id="note-filter" style="max-width:210px" aria-label="Loại mục"><option value="all">Tất cả loại mục</option>${Object.entries(noteTypes).map(([id,l])=>`<option value="${id}" ${noteFilter===id?'selected':''}>${l}</option>`).join('')}</select>${button(icon('download')+' Xuất dữ liệu thử','exportprofile','btn')}</div><div id="note-list">${noteList()}</div><p class="article-note">Học viên tự viết và tổng kết do hệ thống tạo có nguồn khác nhau. Bản thử chưa có AI tự sửa hoặc ghi đè ghi chú.</p>`;}
function editorNote(id=''){const n=P().notes.find(n=>n.id===id)||{type:'note',title:'',body:'',source:'Học viên tự viết',target:''};modal(id?'Sửa mục sổ học tập':'Thêm điều cần nhớ',`<form data-form="note" data-id="${esc(id)}"><label>Loại mục<select name="type">${Object.entries(noteTypes).map(([t,l])=>`<option value="${t}" ${n.type===t?'selected':''}>${l}</option>`).join('')}</select></label><label>Tiêu đề<input name="title" value="${esc(n.title)}" required maxlength="160"></label><label>Nội dung<textarea name="body" rows="5" maxlength="6000" required>${esc(n.body)}</textarea></label><label>Nguồn / bài học<input name="source" value="${esc(n.source)}" maxlength="180"></label><div class="actions"><button type="submit" class="btn primary">Lưu bản thử</button><button type="button" class="btn" data-close>Hủy</button></div><p class="small">Chỉ lưu trong hồ sơ hiện tại trên trình duyệt này.</p></form>`);}
function addNote({type,title,body,source,target='',dedupe=''}){if(dedupe&&P().notes.some(n=>n.dedupe===dedupe)){toast('Mục này đã có trong sổ học tập của hồ sơ hiện tại.');return;}P().notes.unshift({id:uid(),type,title,body,source,target,dedupe,at:new Date().toISOString()});persist('Đã lưu vào sổ học tập trên trình duyệt này.');}
function moduleCards(){return moduleData.filter(m=>moduleFilter==='all'||m[5]===moduleFilter).map(([id,t,d,i,s])=>`<article class="card module-card">${cardIcon(i)}${badge(s,s==='Chưa phát hành'?'muted':'sage')}<h2>${esc(t)}</h2><p>${esc(d)}</p>${link(s==='Chưa phát hành'?'Xem phạm vi dự kiến':'Mở bản mẫu',id,'btn sm','arrow')}${['kana','flash','dictionary','library','characters','reports','achievements'].includes(id)?button(icon('pin'),'pinmodule','iconbutton pin',`data-id="${id}" aria-label="${P().shortcuts.includes(id)?'Bỏ ghim':'Ghim'} ${t}" title="${P().shortcuts.includes(id)?'Đã ghim':'Ghim vào Hôm nay'}"`):''}</article>`).join('');}
function discoverPage(){return `${heading('Khám phá theo cách bạn học.','Tìm công cụ phù hợp. Ghim những mục bạn dùng thường xuyên.','KHÁM PHÁ')}<div class="chiprow filters">${[['all','Tất cả'],['study','Học'],['practice','Luyện tập'],['reference','Tra cứu']].map(([id,l])=>button(l,'modulefilter',`chip ${moduleFilter===id?'active':''}`,`data-filter="${id}"`)).join('')}</div>${notice('<strong>Ghim vào Hôm nay</strong><br>Chọn tối đa ba lối tắt. Ghim chỉ đổi cách truy cập, không mở khóa tính năng chưa phát hành.','', 'pin')}<div id="module-list" class="grid three section">${moduleCards()}</div><div class="section">${link('Xem lộ trình khóa học','learn','textlink','arrow')}</div>`;}
function dictionaryRows(){const result=words.filter(w=>normalize(w.word+' '+w.reading+' '+w.romaji+' '+w.meaning).includes(normalize(dictionaryQuery)));return result.length?result.map(w=>`<article class="wordrow"><span class="jp">${w.word}</span><div><strong>${w.reading}</strong><p>${w.meaning}</p><small class="jp" style="font-size:15px">${w.example}</small></div>${button(icon('note')+' Lưu từ','saveword','btn sm',`data-id="${w.id}"`)}</article>`).join(''):empty('Chưa có mục phù hợp','Bộ mẫu chỉ có sáu từ. Đây chưa phải kết quả tra cứu một từ điển đầy đủ.','search');}
function dictionaryPage(){return `${heading('Hiểu từ trong ngữ cảnh.','Bộ sáu mục để review cách tra và lưu từ. Từ điển đầy đủ chưa phát hành.','TỪ ĐIỂN',badge('Dữ liệu minh họa','sage'))}<div class="searchbox"><input id="dictionary-search" placeholder="Thử: 学生, がくせい, gakusei hoặc học sinh…" value="${esc(dictionaryQuery)}" aria-label="Tra trong sáu từ mẫu">${icon('search')}</div><section class="card section"><div class="inline spread"><h2>Các mục trong bộ mẫu</h2><span class="small">6 từ · không có bản thu</span></div><div id="dictionary-results">${dictionaryRows()}</div></section>`;}
const libraryItems=[['lesson','Giới thiệu bản thân','N5 · Mẫu câu & luyện tập','Bài mẫu','book'],['kana','Nhận diện & luyện viết Kana','Nền tảng · Hiragana / Katakana','Bản mẫu','pen'],['flash','Từ vựng cơ bản','N5 · Bộ sáu thẻ minh họa','Bản mẫu','layers'],['course/N4','Giao tiếp đời sống','N4 · Khung đề xuất','Chưa phát hành','book'],['course/N3','Ngôn ngữ học tập & đời sống','N3 · Khung đề xuất','Chưa phát hành','book'],['course/N2','Đọc và nghe theo ngữ cảnh','N2 · Khung đề xuất','Chưa phát hành','book'],['course/N1','Ngôn ngữ nâng cao','N1 · Khung đề xuất','Chưa phát hành','book']];
function libraryCards(){const catalog=window.NPContentCatalog?NPContentCatalog.list().map(c=>['lesson/'+c.id,c.title,'Bài đọc, mẫu câu & luyện nhớ · Phiên bản '+c.version,'Bài mẫu · v'+c.version,'book']):[],all=[...catalog,...libraryItems.filter(i=>!catalog.length||i[0]!=='lesson')];const list=all.filter(i=>normalize(i[1]+' '+i[2]+' '+i[3]).includes(normalize(libraryQuery)));return list.length?list.map(([r,t,d,s,ic])=>`<article class="card module-card">${cardIcon(ic)}${badge(s,s==='Chưa phát hành'?'muted':'sage')}<h2>${t}</h2><p>${d}</p>${link(s==='Chưa phát hành'?'Xem khung đề xuất':'Mở bài mẫu',r,'btn sm','arrow')}</article>`).join(''):empty('Chưa có nội dung phù hợp','Thư viện hiện chỉ gồm bài mẫu và khung đề xuất. Không có nội dung ẩn đã hoàn thiện.','search');}
function libraryPage(){return `${heading('Một thư viện, nhiều cách học.','Tìm theo mục tiêu, kỹ năng hoặc chủ đề. Trạng thái nội dung luôn nhìn thấy.','THƯ VIỆN BÀI')}<div class="searchbox">${icon('search')}<input id="library-search" value="${esc(libraryQuery)}" placeholder="Tìm: N5, Kana, từ vựng, đọc…" aria-label="Tìm trong thư viện mẫu"></div><div id="library-results" class="grid three section">${libraryCards()}</div>`;}
function characterCards(){const list=characters.filter(c=>(charFilter==='all'||c.group===charFilter)&&normalize(c.name+' '+c.short+' '+c.job).includes(normalize(characterQuery)));return list.length?list.map((c,i)=>`<article class="card character-card"><div class="character-avatar" style="background:${i%2?'var(--lavender)':'var(--sage)'}">${c.short[0]}</div>${badge('Hồ sơ nháp','outline')}<h3 style="margin-top:9px">${esc(c.name)}</h3><small>${esc(c.reading)}</small><p>${esc(c.job)}</p>${link('Xem nhân vật','character/'+c.id,'textlink','arrow')}</article>`).join(''):empty('Chưa có nhân vật phù hợp','Thử tên hoặc nhóm bối cảnh khác.','users');}
function charactersPage(){return `${heading('Gặp lại những người quen, trong câu chuyện mới.','24 nhân vật nháp để xem cấu trúc. Chưa có bộ hội thoại hoàn chỉnh hoặc audio.','NHÂN VẬT & HỘI THOẠI')}${notice('Tên, quan hệ và vai trò dưới đây là đề xuất nội dung mới cho prototype, chưa phải hồ sơ đã được duyệt hoặc bài học phát hành.','neutral')}<div class="toolbar section"><div class="searchbox">${icon('search')}<input id="character-search" placeholder="Tìm nhân vật, công việc…" value="${esc(characterQuery)}" aria-label="Tìm nhân vật nháp"></div><div class="chiprow">${[['all','Tất cả'],['school','Học đường'],['work','Công việc'],['life','Đời sống']].map(([id,l])=>button(l,'charfilter',`chip ${charFilter===id?'active':''}`,`data-filter="${id}"`)).join('')}</div></div><div id="character-results" class="grid four character-grid">${characterCards()}</div>`;}
function characterPage(id){const c=characters.find(c=>c.id===id);if(!c)return notFound();return `${link('Tất cả nhân vật','characters','textlink','back')}${heading(esc(c.name),esc(c.reading)+' · '+esc(c.job),'HỒ SƠ NHÂN VẬT NHÁP',badge('Chưa có hội thoại phát hành','muted'))}<div class="columns"><article class="card"><div class="character-avatar">${esc(c.short[0])}</div><h2>Câu chuyện & bối cảnh</h2><p>${esc(c.bio)}</p><div class="timeline"><div><h3>Bối cảnh ban đầu</h3><p>${esc(c.job)} · thuộc nhóm ${c.group==='school'?'học đường':c.group==='work'?'công việc':'đời sống'}.</p></div><div><h3>Quan hệ trong câu chuyện</h3><p>${esc(c.bio)}</p></div><div><h3>Tình huống có thể phát triển</h3><p>${esc(c.scenarios)}</p></div></div>${notice('Timeline công tác, quan hệ chi tiết và mức ngôn ngữ sẽ được biên soạn riêng, không tự thêm ngày tháng hoặc kinh nghiệm chưa được duyệt.','neutral')}</article><aside class="stack"><section class="card"><h2>Dùng nhân vật để học</h2><p>Hội thoại sau này sẽ gắn với bối cảnh, mục tiêu và quan hệ giữa các nhân vật.</p><div class="divider"></div>${badge('Nội dung chưa phát hành','muted')}<p class="small">Hiện chỉ xem được hồ sơ nháp; chưa có nút phát hoặc học hội thoại giả.</p></section>${link('Về thư viện bài','library','btn','book')}</aside></div>`;}
function legacyReportsPage(){const p=P(),a=p.attempts.at(-1);return `${heading('Tiến bộ cần có bằng chứng.','Dữ liệu của '+esc(p.name)+' trong bản thử trên trình duyệt này.','BÁO CÁO CHI TIẾT',button(icon('download')+' Xuất dữ liệu thử','exportprofile','btn'))}<div class="grid four metric-grid">${[[p.attempts.length,'Lượt kiểm tra mẫu','Không phải chứng nhận trình độ'],[p.writing,'Lượt viết đã lưu','Chưa chấm nét'],[p.flashReviews.length,'Lượt tự đánh giá thẻ','Chưa kiểm tra nhớ bền'],[p.notes.length,'Mục sổ học tập','Gồm ghi chú và mục đã lưu']].map(([n,l,d])=>`<section class="card metric"><span class="small">${l}</span><strong>${n}</strong><small>${d}</small></section>`).join('')}</div><section class="card section"><div class="cardhead"><h2>Bằng chứng theo kỹ năng</h2>${badge('Không gộp thành % tổng','outline')}</div><div class="table-wrap"><table><thead><tr><th>Kỹ năng / hoạt động</th><th>Dữ liệu hiện có</th><th>Giới hạn</th></tr></thead><tbody><tr><td>Ngữ pháp & từ vựng bài mẫu</td><td>${a?a.correct+'/3 câu đúng ở lượt gần nhất; '+a.hints+' câu dùng gợi ý':'Chưa có lượt kiểm tra'}</td><td>Chỉ ba câu minh họa</td></tr><tr><td>Viết Kana</td><td>${p.writing} lượt lưu</td><td>Chưa đánh giá hình dạng hoặc thứ tự nét</td></tr><tr><td>Flashcard</td><td>${p.flashReviews.length} lượt tự đánh giá</td><td>Không suy ra khả năng nhớ lâu</td></tr><tr><td>Nghe / nói / đọc dài</td><td>Chưa có dữ liệu</td><td>Chưa triển khai nội dung và cơ chế kiểm tra</td></tr></tbody></table></div></section><section class="card section"><h2>Lịch sử kiểm tra mẫu</h2>${p.attempts.length?`<div class="table-wrap"><table><thead><tr><th>Thời điểm</th><th>Kết quả</th><th>Dùng gợi ý</th></tr></thead><tbody>${p.attempts.slice().reverse().map(a=>`<tr><td>${new Date(a.at).toLocaleString('vi-VN')}</td><td>${a.correct}/3</td><td>${a.hints} câu</td></tr>`).join('')}</tbody></table></div>`:'<p>Chưa có lượt kiểm tra được ghi nhận. Bạn có thể thử bài mẫu để xem báo cáo thay đổi.</p>'}<div class="actions section">${link('Mở bài mẫu','lesson','btn primary','arrow')}${link('Xem thành tích','achievements','btn','award')}</div></section>`;}
function achievementsPage(){const p=P();const rows=[['Bắt đầu ghi nhớ','Lưu ít nhất một mục vào sổ học tập.',p.notes.length>0,'note'],['Một lượt thử có phản hồi','Hoàn thành bài kiểm tra mẫu.',p.attempts.length>0,'check'],['Tự tay viết thử','Vẽ và lưu ít nhất một lượt luyện Kana.',p.writing>0,'pen'],['Thử ôn bằng thẻ','Lật và tự đánh giá ít nhất một thẻ.',p.flashReviews.length>0,'layers']];return `${heading('Ghi nhận nỗ lực có ý nghĩa.','Cột mốc trong prototype, không phải điểm xếp hạng hoặc chứng chỉ.','THÀNH TÍCH')}<div class="grid two">${rows.map(([t,d,done,i])=>`<article class="card achievement ${done?'':'locked'}"><span class="medal">${icon(done?i:'lock')}</span><div>${badge(done?'Đã ghi nhận trong bản thử':'Chưa ghi nhận',done?'sage':'muted')}<h3 style="margin-top:8px">${t}</h3><p>${d}</p></div></article>`).join('')}</div><div class="section">${notice('Không so sánh thành tích giữa các học viên có độ tuổi, mục tiêu và thời lượng khác nhau.','neutral')}</div>`;}
function goalOptions(goal){return ['Nền tảng','Giao tiếp hằng ngày','N5','N4','N3','N2','N1'].map(v=>`<option value="${esc(v)}" ${goal===v?'selected':''}>${v}</option>`).join('');}
function minuteOptions(value){return [5,10,15,20,30,45,60].map(v=>`<option value="${v}" ${Number(value)===v?'selected':''}>${v} phút</option>`).join('');}
function settingBody(group){const p=P(),pr=p.prefs;switch(group){case 'profile':return `<h2>Hồ sơ của tôi</h2><div class="formgrid"><label>Tên hiển thị<input name="name" required maxlength="60" value="${esc(p.name)}"></label><label>Màu hồ sơ<select name="color">${['Xanh lá trầm','Tím nhạt','Xanh lam','Vàng nhạt'].map((l,i)=>`<option value="${i}" ${p.color===i?'selected':''}>${l}</option>`).join('')}</select></label></div><p class="form-help">Ảnh hiện tại được dùng xuyên suốt không gian học. Chức năng thay ảnh chưa phát hành.</p><div class="divider"></div><label>Cách xưng hô mong muốn<input name="preferredName" maxlength="60" value="${esc(p.preferredName||'')}" placeholder="Không bắt buộc"></label><p class="form-help">Đổi tên không tạo hồ sơ mới và không xóa lịch sử.</p>`;
case 'goals':return `<h2>Mục tiêu & lịch học</h2><div class="formgrid"><label>Tôi học để<select name="purpose">${['Giao tiếp','JLPT','Học tập','Công việc'].map(v=>`<option ${p.purpose===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Mục tiêu hiện tại<select name="goal">${goalOptions(p.goal)}</select><span class="form-help">Mục tiêu học, không phải trình độ đã đạt.</span></label><label class="span2">Khóa đang theo<select name="course"><option value="foundation" ${p.course==='foundation'?'selected':''}>Nền tảng tiếng Nhật · Bản mẫu</option><option value="N5" ${p.course==='N5'?'selected':''}>N5 · Nội dung mẫu</option><option disabled>N4–N1 · Chưa phát hành</option></select></label></div><div class="divider"></div><h3>Nhịp học phù hợp</h3><div class="formgrid section"><label>Thời gian mỗi buổi<select name="minutes">${minuteOptions(p.minutes)}</select></label><div><label>Các ngày học trong tuần</label><div class="daychoices">${['T2','T3','T4','T5','T6','T7','CN'].map(v=>`<label><input type="checkbox" name="days" value="${v}" ${p.days.includes(v)?'checked':''}><span>${v}</span></label>`).join('')}</div><p class="form-help">Có thể đổi kế hoạch trong ngày.</p></div><label class="span2">Ngày mong muốn hoàn thành (không bắt buộc)<input type="date" name="deadline" value="${esc(p.deadline)}"></label></div>${notice('<strong>Đổi mục tiêu không xóa bài đã học.</strong><br>Giá trị mới điều chỉnh cách hiển thị gợi ý; kết quả kiểm tra đã ghi nhận được giữ lại.','lavender')}<div class="data-box">Năng lực đã ghi nhận: ${p.attempts.length?'có kết quả của bài mẫu; chưa đánh giá trình độ.':'chưa có dữ liệu đánh giá.'}</div>`;
case 'learning':return `<h2>Cách học phù hợp với bạn</h2>${NPStudyPreferences.fields(pr.studyPriority)}<div class="divider"></div><div class="formgrid"><label>Furigana — cách đọc Kanji<select name="furigana">${[['always','Luôn hiển thị'],['tap','Chạm để xem'],['hide','Ẩn cách đọc']].map(([v,l])=>`<option value="${v}" ${pr.furigana===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="settings-language"><span>Ngôn ngữ giao diện</span>${Locale.switcher()}<p class="form-help">Áp dụng cho trình duyệt này. Tên riêng, ví dụ tiếng Nhật và ghi chú cá nhân được giữ nguyên.</p></div></div><label class="switchrow"><div><strong>Hiện romaji trong flashcard</strong><p>Hỗ trợ giai đoạn đầu; có thể tắt khi quen Kana.</p></div><input type="checkbox" name="romaji" ${pr.romaji?'checked':''}></label><div class="example"><p class="small">Mẫu hiển thị áp dụng sau khi lưu</p><p class="jp">わたしは<ruby>学生<rt>がくせい</rt></ruby>です。</p><p class="small">Tôi là học sinh / sinh viên.</p></div>${notice('Tốc độ nghe và nhận diện giọng nói chưa có trong bản thử. Không hiển thị kết quả chấm hoặc bản thu giả.','neutral')}`;
case 'display':return `<h2>Hiển thị & hỗ trợ</h2><div class="formgrid"><label>Giao diện<select name="theme"><option value="light" ${pr.theme==='light'?'selected':''}>Sáng · nền kem</option><option value="dark" ${pr.theme==='dark'?'selected':''}>Tối · navy</option></select></label><label>Cỡ chữ Nhật<select name="jpSize">${[24,28,32,36].map(v=>`<option value="${v}" ${pr.jpSize===v?'selected':''}>${v}px</option>`).join('')}</select></label></div><label class="switchrow"><div><strong>Giảm hình minh họa</strong><p>Thu gọn phần trang trí của Michi trong không gian học.</p></div><input name="focus" type="checkbox" ${pr.focus?'checked':''}></label><label class="switchrow"><div><strong>Giảm chuyển động</strong><p>Tắt các chuyển động giao diện không cần thiết.</p></div><input name="motion" type="checkbox" ${pr.motion?'checked':''}></label><div class="section">${button(icon('pin')+' Chỉnh ba lối tắt','shortcuts','btn')}</div>`;
case 'reminders':return `<h2>Nhắc nhở, không gây áp lực</h2>${notice('<strong>Chưa có gửi thông báo.</strong> Các lựa chọn dưới đây chỉ lưu thử cấu hình; chưa kết nối push, email hoặc lịch thiết bị.','neutral')}<label class="switchrow"><div><strong>Muốn nhận lời nhắc học</strong><p>Ý định cấu hình cho phiên bản sau.</p></div><input name="reminders" type="checkbox" ${pr.reminders?'checked':''}></label><div class="formgrid section"><label>Giờ nhắc mong muốn<input type="time" name="remindTime" value="${esc(pr.remindTime)}"></label><label>Múi giờ<select name="timezone"><option>Asia/Tokyo</option></select></label><label>Giờ yên lặng bắt đầu<input name="quietStart" type="time" value="${esc(pr.quietStart)}"></label><label>Giờ yên lặng kết thúc<input name="quietEnd" type="time" value="${esc(pr.quietEnd)}"></label></div><p class="small">Lịch nhắc thật cần được triển khai và kiểm tra riêng. Không có thông báo nào được tạo ở đây.</p>`;
case 'data':return `<h2>Dữ liệu & quyền riêng tư</h2>${notice('<strong>Chỉ lưu thử trên trình duyệt này.</strong><br>Chưa có database, đồng bộ hoặc quyền truy cập server. Không dùng cho ghi chú nhạy cảm.','neutral')}<div class="switchrow"><div><strong>Xuất dữ liệu của hồ sơ hiện tại</strong><p>JSON gồm cấu hình, ghi chú và kết quả trong bản thử.</p></div>${button(icon('download'),'exportprofile','iconbutton','aria-label="Xuất dữ liệu thử"')}</div><div class="switchrow"><div><strong>Chia sẻ báo cáo với gia đình</strong><p>Luồng quyền truy cập chưa triển khai. Không giả lập công tắc bảo mật đã hoạt động.</p></div>${badge('Chưa triển khai','muted')}</div><div class="divider"></div><h3>Đặt lại hoạt động thử của hồ sơ</h3><p class="small">Xóa ghi chú và lượt thử của hồ sơ hiện tại. Giữ tên, mục tiêu và các hồ sơ khác.</p><div class="section">${button('Đặt lại hoạt động thử','resetprofile','btn danger')}</div>`;
case 'account':return `<h2>Tài khoản & bảo mật</h2>${notice('<strong>Đây là bản review giao diện.</strong> Chưa có đăng nhập thật, khôi phục mật khẩu hoặc phân quyền server.','neutral')}<div class="switchrow"><div><strong>Xác thực tài khoản</strong><p>Chọn phương án phù hợp cho người lớn và hồ sơ trẻ em khi triển khai.</p></div>${badge('Chưa kết nối','muted')}</div><div class="switchrow"><div><strong>Vai trò trong nhóm mẫu</strong><p>${p.role==='manager'?'Quản lý gia đình mẫu':'Học viên mẫu'} · Không tự nâng quyền trong cấu hình.</p></div>${icon('shield')}</div><div class="actions section">${link('Xem màn đăng nhập','login','btn','lock')}${link('Chọn hồ sơ khác','profiles','btn','users')}</div><p class="small">PIN chuyển hồ sơ, nếu có về sau, không thay thế xác thực và quyền truy cập server.</p>`;
default:return '';
}}
function settingsPage(group='goals'){if(!settingGroups.some(g=>g[0]===group))group='goals';const readonly=['data','account'].includes(group);return `${heading('Không gian của tôi','Điều chỉnh việc học theo cách phù hợp với bạn.','CÁ NHÂN')}<section class="card profile-strip">${avatar(P(),true)}<div><h2 data-no-translate>${esc(P().name)}</h2><p class="muted">Hồ sơ cá nhân · Mục tiêu ${esc(P().goal)}</p></div>${link('Sửa hồ sơ','settings/profile','btn sm','pen')}</section><div class="settings-layout"><nav class="card settings-menu" aria-label="Nhóm cấu hình cá nhân">${settingGroups.map(([id,l,ic])=>`<a href="#settings/${id}" class="${id===group?'active':''}" ${id===group?'aria-current="page"':''}>${icon(ic)} ${l}</a>`).join('')}</nav><div><select class="settings-select" aria-label="Chọn nhóm cấu hình">${settingGroups.map(([id,l])=>`<option value="${id}" ${id===group?'selected':''}>${l}</option>`).join('')}</select><form class="card settings-form" data-form="settings" data-group="${group}">${settingBody(group)}${readonly?'':`<div class="settings-footer"><span class="small">Áp dụng cho ${esc(P().name)} · lưu trên trình duyệt này</span><div class="actions">${button('Hủy thay đổi','cancelsettings','btn')}<button type="submit" class="btn primary">Lưu bản thử</button></div></div>`}</form></div></div>`;}
function profilePage(){const p=P();return `${heading('Hồ sơ học viên','Thông tin được lấy từ dữ liệu hồ sơ và có thể chỉnh sửa.','CÁ NHÂN',link('Không gian của tôi','settings/profile','btn','gear'))}<section class="card profile-strip">${avatar(p,true)}<div><h2 data-no-translate>${esc(p.name)}</h2><p>${esc(p.purpose)} · ${p.minutes} phút mỗi buổi</p></div>${badge(p.role==='manager'?'Quản lý gia đình mẫu':'Học viên mẫu','sage')}</section><div class="grid three"><section class="card"><h2>Mục tiêu mong muốn</h2><p class="quote">${esc(p.goal)}</p><p>Do bạn chọn. Không phải trình độ đã đạt.</p>${link('Đổi mục tiêu','settings/goals','textlink','arrow')}</section><section class="card"><h2>Khóa đang theo</h2><p>${p.course==='N5'?'N5 · Nội dung mẫu':'Nền tảng tiếng Nhật · Bản mẫu'}</p>${link('Xem lộ trình','course/'+p.course,'textlink','arrow')}</section><section class="card"><h2>Năng lực ghi nhận</h2><p>${p.attempts.length?'Có kết quả bài mẫu; chưa đánh giá trình độ.':'Chưa có dữ liệu đánh giá.'}</p>${link('Xem bằng chứng','reports','textlink','arrow')}</section></div><div class="actions section">${link('Sổ học tập','notebook','btn','note')}${link('Thành tích','achievements','btn','award')}${link('Gia đình','family','btn','users')}${link('Chọn người học khác','profiles','btn ghost')}</div>`;}
function familyPage(){const manager=P().role==='manager';return `${heading('Mỗi người một không gian riêng.','Danh sách mẫu có thể thêm, sửa hoặc lưu trữ; không cố định bốn người trong code.','GIA ĐÌNH',manager?button(icon('plus')+' Thêm học viên mẫu','addprofile','btn primary'):'')}${notice('<strong>Quản lý gia đình mẫu.</strong> Chưa có tài khoản server, gửi lời mời hoặc phân quyền production. Màn này chỉ giúp review bố cục và vòng đời hồ sơ.','neutral')}${!manager?`<section class="card section"><h2>Hồ sơ hiện tại là học viên</h2><p>Quyền thêm hoặc lưu trữ người học được tách khỏi cấu hình cá nhân.</p><div class="section">${link('Chọn hồ sơ quản lý mẫu','profiles','btn','users')}</div></section>`:''}<section class="card section"><div class="cardhead"><h2>Học viên đang hoạt động</h2><span class="count-label">${db.profiles.filter(p=>!p.archived).length}</span></div>${db.profiles.filter(p=>!p.archived).map(p=>`<div class="family-row">${avatar(p)}<div><strong data-no-translate>${esc(p.name)}</strong><small>${p.role==='manager'?'Quản lý gia đình mẫu':p.role==='guest'?'Khách thử':'Học viên mẫu'}</small></div>${p.id===P().id?badge('Đang chọn','sage'):''}${manager&&p.role!=='manager'?`<div class="actions">${button('Lưu trữ','archiveprofile','btn sm',`data-id="${esc(p.id)}"`)}</div>`:''}</div>`).join('')}<div class="actions section">${manager?button(icon('mail')+' Mời qua tài khoản','invite','btn'):''}${link('Cấu hình của tôi','settings/profile','btn ghost')}</div></section>${manager&&db.profiles.some(p=>p.archived)?`<section class="card section"><h2>Hồ sơ đã lưu trữ</h2>${db.profiles.filter(p=>p.archived).map(p=>`<div class="family-row archived">${avatar(p)}<div><strong data-no-translate>${esc(p.name)}</strong><small>Dữ liệu thử vẫn được giữ</small></div>${button('Khôi phục','restoreprofile','btn sm',`data-id="${esc(p.id)}"`)}</div>`).join('')}</section>`:''}<p class="article-note">Quyền xem báo cáo và quyền đọc ghi chú riêng cần được thiết kế riêng. Không mặc định quản lý gia đình được đọc toàn bộ sổ của người khác.</p>`;}
function guidePage(){const faqs=[['Tôi nên bắt đầu ở đâu?','Tại Home–Login, chọn avatar và dùng mã PATH-DEMO để vào Dashboard. Hồ sơ mới sẽ qua bước chọn mục tiêu. Chọn Khách để thử không cần mã. Liên kết “Toàn bộ trang” ở cuối Home mở danh sách mọi màn hình.'],['Mục tiêu và trình độ khác nhau thế nào?','Mục tiêu do bạn chọn. Kết quả bài mẫu chỉ mô tả lượt trả lời cụ thể, chưa xác nhận trình độ JLPT hoặc mức thành thạo.'],['Những gì đang dùng được trong prototype?','Chuyển hồ sơ, thêm/lưu trữ hồ sơ mẫu từ tài khoản quản lý mẫu, lưu cấu hình, vẽ Kana, lật thẻ, làm ba câu kiểm tra, ghi chú, lọc dữ liệu và xuất JSON. Tất cả chỉ lưu trên trình duyệt này.'],['Phần nào chưa triển khai?','Đăng nhập thật, database, sync đa thiết bị, lịch ôn tự động, audio đóng gói, AI hội thoại, chấm nét/chấm nói và các khóa đầy đủ N5–N1 chưa triển khai. Nhân vật là bản nháp, từ điển chỉ có sáu mục.'],['Cách review trên PC, tablet và mobile?','Dùng các nút PC / Tablet / Mobile ở thanh review khi xem trên PC. Trên điện thoại, bố cục tự chuyển thành một cột và thanh điều hướng dưới. Vùng viết hỗ trợ chạm.'],['Furigana và romaji chỉnh ở đâu?','Vào bánh răng cạnh avatar → Cách học. Chế độ furigana “Chạm để xem” cho phép chạm chữ có cách đọc trong bài mẫu. Romaji chỉ tác động flashcard.'],['Dữ liệu có đồng bộ giữa thiết bị không?','Chưa. Dữ liệu thuộc trình duyệt đang mở. Có thể xuất JSON của hồ sơ hiện tại; bản thử chưa có chức năng nhập hoặc đồng bộ.'],['Thêm người học có cần sửa code không?','Không trong bản thử này. Hồ sơ được thêm vào danh sách dữ liệu qua màn Quản lý gia đình. Tài khoản/xác thực thực tế cần backend riêng.'],['Michi có đang dùng AI không?','Không. Gợi ý trong prototype dựa vào mục tiêu, bài dở và kết quả mẫu. Chưa có cuộc gọi AI, phân tích giọng nói hoặc hệ thống gợi ý thích ứng đầy đủ.']];return `${heading('Dễ bắt đầu. Biết rõ mình đang dùng gì.','Hướng dẫn học và cách review prototype.','HƯỚNG DẪN')}<div class="columns"><section class="card guide"><h2>Những điều cần biết</h2>${faqs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><aside class="stack"><section class="card"><h2>Flow nên thử</h2><ol class="instructions"><li>Chọn người học.</li><li>Đổi tên hoặc mục tiêu.</li><li>Học bài mẫu và trả lời ba câu.</li><li>Lưu tổng kết vào sổ.</li><li>Đổi hồ sơ để kiểm tra dữ liệu tách riêng.</li></ol><div class="section">${link('Bắt đầu từ đăng nhập','login','btn primary wide','arrow')}</div></section>${link('Mở sơ đồ toàn bộ trang','map','btn','map')}</aside></div>`;}
function assistantPage(){const p=P();return `${heading('Một lời gợi ý, có lý do.','Michi trong bản thử dùng quy tắc minh bạch, chưa phải trợ lí AI trực tuyến.','BẠN ĐỒNG HÀNH')}<div class="columns"><div class="stack">${michiCard(p.resume?'Bạn có một bài mẫu đang dở. Mình có thể giúp bạn quay lại đúng phần đó.':'Bạn có thể bắt đầu bằng một bài mẫu ngắn. Khi chưa có lịch sử, mình chưa biết kỹ năng nào của bạn cần ôn nhất.')}<section class="card"><h2>Gợi ý này dựa vào đâu?</h2><div class="checklist"><div>${icon('compass')}<span>Mục tiêu bạn đã chọn: <strong>${esc(p.goal)}</strong>.</span></div><div>${icon('clock')}<span>Thời lượng hôm nay: <strong>${p.todayMinutes||p.minutes} phút</strong>.</span></div><div>${icon('book')}<span>${p.resume?'Có vị trí trong bài mẫu đã mở.':'Chưa có vị trí học tiếp.'}</span></div><div>${icon('chart')}<span>${p.attempts.length?p.attempts.length+' lượt kiểm tra mẫu, không đủ để kết luận trình độ.':'Chưa có kết quả để nhận định điểm yếu.'}</span></div></div><div class="actions section">${link(p.resume?'Học tiếp bài mẫu':'Xem bài mẫu','lesson','btn primary','play')}${link('Đổi kế hoạch','settings/goals','btn')}</div></section></div><aside class="stack"><section class="card"><h2>Bạn luôn có lựa chọn</h2><p>Rút ngắn buổi học, thay mục tiêu hoặc thu gọn Michi. Gợi ý không thay cho quyết định của bạn.</p><div class="actions section">${link('Cách hiển thị','settings/display','btn sm')}${link('Nhắc nhở','settings/reminders','btn sm')}</div></section><section class="card"><h2>Chưa triển khai</h2><p>AI chat, tự tạo bài học, đánh giá giọng nói và gửi nhắc nhở chưa hoạt động. Không có phản hồi AI giả trong bản thử.</p></section></aside></div>`;}
function listeningPage(){return `${heading('Luyện nghe & nói','Phạm vi dự kiến để review thiết kế; chưa phát hành.','MODULE TƯƠNG LAI',badge('Chưa phát hành','muted'))}<div class="columns"><section class="card"><h2>Luồng dự kiến</h2><ol class="instructions"><li>Chọn nội dung có nguồn âm thanh được kiểm tra.</li><li>Nghe theo ngữ cảnh và trả lời.</li><li>Thử nói nếu cơ chế thu âm đã triển khai.</li><li>Xem phản hồi có giới hạn và bằng chứng.</li></ol></section><section class="card"><h2>Chưa có audio hoặc chấm nói</h2><p>Không có nút phát, waveform hoặc điểm phát âm mô phỏng như kết quả thật.</p><div class="section">${link('Về Khám phá','discover','btn','back')}</div></section></div>`;}
function notFound(){return heading('Chưa tìm thấy màn hình này.','Bạn có thể quay lại danh sách trang để tiếp tục review.','ĐIỀU HƯỚNG')+empty('Quay lại hành trình','Không có nội dung bị ẩn ở địa chỉ này.','map',link('Sơ đồ trang','map','btn primary','arrow'));}
function applyPrefs(){const pr=P().prefs;document.body.classList.toggle('dark',pr.theme==='dark');document.body.classList.toggle('hide-furigana',pr.furigana==='hide');document.body.classList.toggle('tap-furigana',pr.furigana==='tap');document.body.classList.toggle('reduce-motion',pr.motion);document.body.classList.toggle('focus-mode',pr.focus);document.documentElement.style.setProperty('--jp-size',pr.jpSize+'px');}
function applyDevice(){const narrow=device==='mobile'||innerWidth<760;document.body.classList.toggle('compact',narrow);document.body.classList.toggle('preview-narrow',device==='mobile'&&innerWidth>=760);document.body.classList.toggle('device-tablet',device==='tablet'&&innerWidth>=760);for(const el of document.querySelectorAll('[data-device]'))el.setAttribute('aria-pressed',String(el.dataset.device===device));if(route()==='kana')requestAnimationFrame(setupCanvas);}

const accessRoutes=new Set(['login','profiles','onboarding','forgot','recovery','reset-access','reset-done','invite','invite-preview','join','ready','logout']);
let accessError='',inviteError='',resetError='',recoverTargetId='',rememberDemoProfile=!!db.demoLoginProfile;
function accessSteps(active){return `<nav class="access-steps" aria-label="Các bước bắt đầu">${[['Truy cập','login'],['Hồ sơ','profiles'],['Mục tiêu','onboarding'],['Bắt đầu','ready']].map(([l,r],i)=>`<span class="access-step ${i+1===active?'current':i+1<active?'done':''}" ${i+1===active?'aria-current="step"':''}><span>${i+1<active?icon('check'):i+1}</span><b>${l}</b></span>`).join('')}</nav>`;}
function accessPage(title,lead,body,step=1,ic='lock'){return `<section class="auth-shell access-shell">${authTop()}<main id="main" class="auth-main" tabindex="-1"><div class="access-flow-wrap">${accessSteps(step)}<section class="card access-flow-card"><div class="access-page-icon">${icon(ic)}</div><h1>${title}</h1><p class="access-lead">${lead}</p>${body}</section><div class="access-flow-links">${link('Quay lại Login','login','textlink','back')}${link('Sơ đồ trang','map','textlink','map')}</div></div></main><footer class="access-footer"><span>UI demo · Chưa có xác thực server hoặc gửi email.</span><span>Nihongo Path</span></footer></section>`;}
function forgotPage(){return accessPage('Lấy lại quyền truy cập.','Màn khôi phục mẫu. Không gửi email hoặc thay đổi tài khoản thật.',`<form data-form="recover"><label>Hồ sơ mẫu cần khôi phục<select name="learner">${db.profiles.filter(p=>!p.archived).map(p=>`<option value="${esc(p.id)}" ${p.id===P().id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><p class="form-help">Phiên bản có backend sẽ xác minh danh tính trước khi cho đặt lại mật khẩu.</p><button type="submit" class="btn primary wide section">Xem bước khôi phục ${icon('arrow')}</button></form>`,1,'help');}
function recoveryPage(){const p=db.profiles.find(p=>p.id===recoverTargetId)||P();return accessPage('Kiểm tra bước tiếp theo.','Đây là trạng thái chờ xác nhận của luồng khôi phục.',`<div class="recovery-target">${avatar(p)}<div><strong data-no-translate>${esc(p.name)}</strong><small>Hồ sơ mẫu được chọn</small></div></div>${notice('<strong>Chưa có email nào được gửi.</strong><br>Khi triển khai thật, liên kết khôi phục sẽ được gửi qua kênh đã xác minh. Bản demo chỉ cho xem bước tiếp theo.','neutral')}<div class="section">${link('Xem màn đặt lại mẫu','reset-access','btn primary wide','arrow')}</div>${link('Chọn hồ sơ khác','forgot','textlink')}`,1,'mail');}
function resetAccessPage(){return accessPage('Đặt lại thông tin truy cập.','Chỉ dùng giá trị mẫu để kiểm tra cách nhập và xử lý lỗi.',`<form data-form="reset-access" autocomplete="off"><label>Mật khẩu mới — mẫu<input name="samplePassword" type="password" minlength="8" required autocomplete="off" placeholder="Ví dụ: PathDemo2026"></label><label>Nhập lại mật khẩu mẫu<input name="sampleConfirm" type="password" minlength="8" required autocomplete="off" placeholder="Nhập lại giá trị ở trên"></label><p id="reset-error" class="field-error" role="alert" ${resetError?'':'hidden'}>${esc(resetError)}</p><p class="form-help">Không nhập mật khẩu thật. Hai giá trị chỉ được đối chiếu tại đây, không lưu hoặc gửi.</p><button type="submit" class="btn primary wide section">Hoàn tất bước mô phỏng ${icon('arrow')}</button></form>`,1,'shield');}
function resetDonePage(){return accessPage('Đã xem xong flow khôi phục.','Các bước nhập và xác nhận đã được kiểm tra trong bản mô phỏng.',`${notice('<strong>Không có mật khẩu tài khoản nào được thay đổi.</strong><br>Mã vào bản demo vẫn là PATH-DEMO. Dữ liệu học thử được giữ nguyên.','neutral')}<div class="section">${link('Về Login','login','btn primary wide','arrow')}</div>`,1,'check');}
function invitePage(){return accessPage('Cùng học trong một gia đình.','Nhập mã mẫu để xem luồng tham gia nhóm và tạo hồ sơ.',`<form data-form="invite"><label>Mã mời demo<input name="inviteCode" required maxlength="40" autocomplete="off" placeholder="PATH-FAMILY" style="text-transform:uppercase;letter-spacing:1px"></label><div class="demo-code-help"><span>Mã mẫu: <code>PATH-FAMILY</code></span>${button('Điền mã mẫu','fillinvite','textlink')}</div><p id="invite-error" class="field-error" role="alert" ${inviteError?'':'hidden'}>${esc(inviteError)}</p><button type="submit" class="btn primary wide section">Kiểm tra mã mẫu ${icon('arrow')}</button></form><p class="auth-disclosure">Mã được công khai để thử giao diện. Chưa có lời mời hoặc quyền truy cập nhóm thật.</p>`,1,'mail');}
function invitePreviewPage(){return accessPage('Gia đình mẫu Nihongo Path','Xem trước thông tin nhóm trước khi tạo hồ sơ riêng.',`<div class="invite-family"><span class="invite-family-mark">${icon('users')}</span><div><strong>Nhóm học gia đình · mẫu</strong><small>${db.profiles.filter(p=>!p.archived&&p.role!=='guest').length} hồ sơ thử hiện tại · Có thể thêm người học</small></div></div><div class="access-checklist"><span>${icon('check')} Mục tiêu và tùy chọn riêng</span><span>${icon('check')} Sổ học tập theo hồ sơ</span><span>${icon('check')} Giữ lịch sử khi đổi mục tiêu</span></div>${notice('Đây là thông tin minh họa. Mã demo không cấp quyền vào tài khoản hoặc dữ liệu thật.','neutral')}<div class="section">${link('Tạo hồ sơ thử của tôi','join','btn primary wide','plus')}</div>${link('Tôi đã có hồ sơ mẫu','profiles','textlink')}`,2,'users');}
function joinPage(){return accessPage('Tạo một không gian của riêng bạn.','Chỉ tạo hồ sơ dữ liệu thử. Không tạo tài khoản đăng nhập thật.',`<form data-form="join"><label>Tên hiển thị<input name="name" required maxlength="60" placeholder="Bạn muốn được gọi thế nào?"></label><label>Màu avatar<select name="color"><option value="0">Xanh lá trầm</option><option value="1">Tím nhạt</option><option value="2">Xanh lam</option><option value="3">Champagne</option></select></label><p class="form-help">Không cần ngày sinh, số điện thoại hoặc email để review bản mẫu.</p><button type="submit" class="btn primary wide section">Tạo hồ sơ thử ${icon('arrow')}</button></form>`,2,'user');}
function readyPage(){return accessPage('Sẵn sàng cho bước đầu tiên.','Bạn có thể đổi mọi lựa chọn này trong Không gian của tôi.',`<div class="ready-profile">${avatar(P(),true)}<h2 data-no-translate>${esc(P().name)}</h2><span>${esc(P().goal)} · ${P().minutes} phút mỗi buổi</span></div><div class="access-checklist"><span>${icon('compass')} Mục tiêu học đã được chọn</span><span>${icon('note')} Sổ học tập riêng đã có chỗ lưu</span><span>${icon('gear')} Có thể điều chỉnh nhịp học sau</span></div>${notice('Nội dung hiện có là bài mẫu để review. Chưa có khóa đầy đủ hoặc đánh giá trình độ.','neutral')}<div class="section">${link('Vào Dashboard của tôi','today','btn primary wide','arrow')}</div>${link('Chỉnh lại mục tiêu','onboarding','textlink')}`,4,'leaf');}
function logoutPage(){return accessPage('Đã thoát bản trải nghiệm.','Bạn có thể quay lại mà không mất ghi chú hoặc kết quả thử.',`${notice('Thao tác này chỉ kết thúc luồng demo trên giao diện, không phải đăng xuất một tài khoản server.','neutral')}<div class="section">${link('Về Login','login','btn primary wide','arrow')}</div>`,1,'logout');}


// Canonical routes delegate to the pilot, retaining the original view for comparison/history.
function lessonPage(){return window.NPLessonUI&&!NPLessonUI.baseline()?NPLessonUI.page():legacyLessonPage();}
function quizPage(){return window.NPLessonUI&&!NPLessonUI.baseline()?NPLessonUI.page('practice'):legacyQuizPage();}
function summaryPage(){return window.NPLessonUI&&!NPLessonUI.baseline()?NPLessonUI.summary():legacySummaryPage();}
function reviewPage(){if(!window.NPLessonUI||NPLessonUI.baseline())return legacyReviewPage();return legacyReviewPage().replace(/<div class="notice neutral">[\s\S]*?<\/div><\/div>/,NPLessonUI.reviewPanel()).replace('Làm bài kiểm tra mẫu để có câu cần xem lại.','Xem câu chưa đúng hoặc đã dùng gợi ý trong bài N5.').replace('Nếu chưa có lịch sử học, hãy thử một hoạt động ngắn. Mình chưa kết luận bạn yếu phần nào.','Mở lịch ôn để gặp lại mẫu đã học. Nếu chưa bắt đầu, một bài ngắn là đủ cho hôm nay.');}
function mistakesPage(){return window.NPLessonUI&&!NPLessonUI.baseline()?NPLessonUI.mistakesPage()+(P().attempts.length?legacyMistakesPage():''):legacyMistakesPage();}
function reportsPage(){return legacyReportsPage()+(window.NPLessonUI&&!NPLessonUI.baseline()?NPLessonUI.reportPanel():'');}

function render(scroll=true){const preview=new URLSearchParams(location.search).has('content-preview'),requested=route(),r=preview&&!['lesson','quiz','summary'].includes(requested.split('/')[0])?'lesson':requested,base=r.split('/')[0];document.body.classList.toggle('content-preview',preview);document.body.classList.toggle('is-admin',base==='admin');document.body.classList.toggle('is-login',base==='login');applyPrefs();if(preview)document.body.classList.toggle('dark',new URLSearchParams(location.search).get('preview-theme')==='dark');let content;switch(base){case 'login':content=loginPage();break;case 'forgot':content=forgotPage();break;case 'recovery':content=recoveryPage();break;case 'reset-access':content=resetAccessPage();break;case 'reset-done':content=resetDonePage();break;case 'invite':content=invitePage();break;case 'invite-preview':content=invitePreviewPage();break;case 'join':content=joinPage();break;case 'ready':content=readyPage();break;case 'logout':content=logoutPage();break;case 'profiles':content=profilesPage();break;case 'guest':{let g=db.profiles.find(p=>p.id==='guest');if(!g){g=structuredClone(initialProfiles[0]);Object.assign(g,{id:'guest',name:'Khách',role:'guest',goal:'Nền tảng',minutes:10,color:2,onboarded:true});db.profiles.push(g);}g.archived=false;db.current=g.id;resetLearningView();persist();go('today');return;}case 'admin':content=window.NPAdminUI?NPAdminUI.page():notice('Đang mở xưởng nội dung…','neutral');break;case 'map':content=mapPage();break;case 'onboarding':content=onboardingPage();break;case 'today':content=todayPage();break;case 'learn':content=learnPage();break;case 'course':content=coursePage(r.split('/')[1]);break;case 'lesson':content=lessonPage();break;case 'quiz':if(quizFinished&&(!window.NPLessonUI||NPLessonUI.baseline()))resetQuiz();content=quizPage();break;case 'summary':content=summaryPage();break;case 'review':content=reviewPage();break;case 'kana':content=kanaPage();break;case 'flash':content=flashPage();break;case 'mistakes':content=mistakesPage();break;case 'notebook':content=notebookPage();break;case 'discover':content=discoverPage();break;case 'dictionary':content=dictionaryPage();break;case 'library':content=libraryPage();break;case 'characters':content=charactersPage();break;case 'character':content=characterPage(r.split('/')[1]);break;case 'reports':content=reportsPage();break;case 'achievements':content=achievementsPage();break;case 'settings':content=settingsPage(r.split('/')[1]||'goals');break;case 'profile':content=profilePage();break;case 'family':content=familyPage();break;case 'guide':content=guidePage();break;case 'assistant':content=assistantPage();break;case 'listening':content=listeningPage();break;default:content=notFound();}const auth=accessRoutes.has(base);$('#app').innerHTML=base==='admin'?content:preview?'<main class="preview-main" id="main" tabindex="-1">'+content+'</main>':auth?content:shell(content);document.title=(base==='map'?'Toàn bộ trang & flow':titleOf(r))+' · Nihongo Path';Locale.translate(document);applyDevice();if(base==='kana')requestAnimationFrame(setupCanvas);if(window.NPLessonUI)NPLessonUI.mount();if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}if(base==='admin'&&window.NPAdminUI)NPAdminUI.mount();}
let drawingSaved=false,canvasContext=null;
function setupCanvas(){const canvas=$('#writing');if(!canvas)return;const rect=canvas.getBoundingClientRect(),ratio=window.devicePixelRatio||1;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);ctx.lineWidth=5;ctx.strokeStyle='#20384d';ctx.lineCap='round';ctx.lineJoin='round';canvasContext={ctx,width:rect.width,height:rect.height};redraw();if(canvas.dataset.bound)return;canvas.dataset.bound='true';let drawing=false;const pt=e=>{const b=canvas.getBoundingClientRect();return [(e.clientX-b.left)/b.width,(e.clientY-b.top)/b.height];};canvas.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;drawingSaved=false;currentStroke=[pt(e)];canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drawing)return;currentStroke.push(pt(e));redraw();});const end=()=>{if(!drawing)return;drawing=false;if(currentStroke.length===1){const [x,y]=currentStroke[0];currentStroke.push([x+.001,y+.001]);}strokeHistory.push(currentStroke);currentStroke=[];redraw();};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);}
function redraw(){if(!canvasContext)return;const {ctx,width,height}=canvasContext;ctx.clearRect(0,0,width,height);for(const stroke of [...strokeHistory,currentStroke]){if(!stroke.length)continue;ctx.beginPath();ctx.moveTo(stroke[0][0]*width,stroke[0][1]*height);for(const [x,y] of stroke.slice(1))ctx.lineTo(x*width,y*height);ctx.stroke();}}
function resetQuiz(){quizAnswers=[];quizIndex=0;quizSelected=null;quizChecked=false;quizHints=[];quizFinished=false;}
function resetLearningView(){resetQuiz();lessonStep=0;flashIndex=0;flashFlipped=false;strokeHistory=[];currentStroke=[];drawingSaved=false;noteQuery='';dictionaryQuery='';libraryQuery='';characterQuery='';noteFilter='all';charFilter='all';}
function exportProfile(){const data={schemaVersion:1,prototype:true,exportedAt:new Date().toISOString(),profile:P(),learning:window.NPLessonUI?NPLessonUI.read():null};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Nihongo_Path_Profile_'+P().id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã tạo file JSON của hồ sơ hiện tại.');}
function profileMenu(){modal('Không gian của '+P().name,`<div class="profilemenu">${[['profile','user','Hồ sơ của tôi'],['settings/goals','gear','Không gian của tôi'],['reports','chart','Báo cáo'],['achievements','award','Thành tích'],['family','users','Gia đình'],['profiles','review','Đổi người học'],['logout','logout','Đăng xuất demo']].map(([r,i,l])=>`<a href="#${r}" data-close-link>${icon(i)}${l}</a>`).join('')}</div><p class="small">Prototype · không phải phiên đăng nhập thật.</p>`);}
function addProfileModal(){if(P().role!=='manager'){modal('Quyền quản lý gia đình mẫu',`<p>Hồ sơ hiện tại không có quyền thêm người học trong bản thử. Chọn hồ sơ Learner A để review luồng quản lý.</p><div class="section">${link('Chọn người học','profiles','btn primary')}</div>`);return;}modal('Thêm học viên mẫu',`<form data-form="addprofile"><label>Tên hiển thị<input name="name" required maxlength="60" placeholder="Tên người học"></label><label>Mục tiêu ban đầu<select name="goal">${goalOptions('Nền tảng')}</select></label><label>Thời gian mỗi buổi<select name="minutes">${minuteOptions(15)}</select></label><p class="small">Tạo hồ sơ dữ liệu thử trên trình duyệt này, không tạo tài khoản hoặc gửi email.</p><div class="actions"><button class="btn primary" type="submit">Thêm hồ sơ thử</button><button class="btn" type="button" data-close>Hủy</button></div></form>`);}
function shortcutModal(){modal('Lối tắt của tôi',`<p>Chọn tối đa ba mục. Lối tắt không làm thay đổi quyền hoặc trạng thái module.</p><form data-form="shortcuts">${[...moduleData.filter(m=>m[0]!=='listening'),['notebook','Sổ học tập','','note']].map(([id,t])=>`<label class="switchrow"><span>${t}</span><input type="checkbox" name="shortcuts" value="${id}" ${P().shortcuts.includes(id)?'checked':''}></label>`).join('')}<div class="actions"><button type="submit" class="btn primary">Lưu ba lối tắt</button><button type="button" class="btn" data-close>Hủy</button></div></form>`);}
let settingsDirty=false,pendingRoute='';
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a){if(a.getAttribute('href')==='#main'){e.preventDefault();$('#main')?.focus();return;}if(settingsDirty){e.preventDefault();pendingRoute=a.hash.slice(1);modal('Bạn có thay đổi chưa lưu',`<p>Giữ lại để tiếp tục chỉnh hoặc bỏ thay đổi và đi sang trang khác.</p><div class="actions">${button('Tiếp tục chỉnh','staysettings','btn primary')}${button('Bỏ thay đổi & đi tiếp','discardsettings','btn')}</div>`);return;}closeModal();}if(e.target.closest('[data-close]')){closeModal();return;}const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case 'loginprofile':if(!NPLogin.isBaseline()&&id!=='guest'){NPLogin.open(id,b);}else{loginSelected=id;accessError='';render(false);[...document.querySelectorAll('.family-choice')].find(el=>el.dataset.id===id)?.focus({preventScroll:true});}break;case 'profilemenu':profileMenu();break;case 'fillcode':{const el=$('[name=demoCode]');if(el){el.value='PATH-DEMO';el.removeAttribute('aria-invalid');accessError='';const err=$('#login-error');if(err)err.hidden=true;el.focus();}break;}case 'fillinvite':{const el=$('[name=inviteCode]');if(el){el.value='PATH-FAMILY';el.focus();}break;}case 'togglecode':{const el=$('[name=demoCode]');if(el){el.type=el.type==='password'?'text':'password';b.setAttribute('aria-label',el.type==='password'?I('Hiện mã demo','Show demo code','サンプルコードを表示'):I('Ẩn mã demo','Hide demo code','サンプルコードを隠す'));}break;}case 'quicknav':modal('Đi đến màn hình',`<div class="profilemenu">${[['map','Sơ đồ toàn bộ trang'],['today','Hôm nay'],['learn','Học'],['review','Ôn'],['notebook','Sổ học tập'],['discover','Khám phá'],['reports','Báo cáo'],['achievements','Thành tích'],['settings/goals','Không gian của tôi'],['family','Gia đình'],['guide','Hướng dẫn']].map(([r,l])=>link(l,r,'')).join('')}</div>`);break;
case 'forgot':go('forgot');break;
case 'invite':inviteError='';go('invite');break;
case 'selectprofile':if(db.profiles.some(p=>p.id===id&&!p.archived)){db.current=id;settingsDirty=false;resetLearningView();lessonStep=Math.min(2,Math.max(0,P().resume?.step||0));persist();go(P().onboarded?'today':'onboarding');}break;
case 'addprofile':addProfileModal();break;
case 'minutes':P().todayMinutes=Number(b.dataset.minutes);persist();render(false);break;
case 'shortcuts':shortcutModal();break;
case 'pinmodule':{const arr=P().shortcuts,ix=arr.indexOf(id);if(ix>=0)arr.splice(ix,1);else if(arr.length>=3){toast('Đã có ba lối tắt. Bỏ ghim một mục trước.');break;}else arr.push(id);persist(ix>=0?'Đã bỏ ghim trên hồ sơ này.':'Đã ghim vào Hôm nay.');render(false);break;}
case 'modulefilter':moduleFilter=b.dataset.filter;render(false);break;
case 'charfilter':charFilter=b.dataset.filter;render(false);break;
case 'lessonstep':lessonStep=Number(b.dataset.step);render(false);break;
case 'lessonprev':lessonStep=Math.max(0,lessonStep-1);render(false);break;
case 'lessonnext':lessonStep=Math.min(2,lessonStep+1);render(false);break;
case 'savelesson':{const s=lessonSteps[lessonStep];addNote({type:'sentence',title:s.jp.replace(/<rt>.*?<\/rt>/g,'').replace(/<[^>]*>/g,''),body:s.meaning+'\n'+s.tip,source:'N5 · Bài minh họa · '+s.label,target:'lesson',dedupe:'lesson-'+lessonStep});break;}
case 'noaudio':modal('Chưa có bản thu',`<p>Bản thử chưa đóng gói audio. Không tự phát TTS rồi coi đó là bản thu bài học đã được kiểm tra.</p>`);break;
case 'quizselect':if(!quizChecked){quizSelected=Number(b.dataset.index);render(false);}break;
case 'quizhint':quizHints[quizIndex]=true;render(false);break;
case 'quizcheck':if(quizSelected!==null&&!quizChecked){quizChecked=true;quizAnswers[quizIndex]=quizSelected;render(false);}break;
case 'quiznext':if(!quizChecked)break;if(quizIndex<2){quizIndex++;quizSelected=null;quizChecked=false;render();}else{const a={id:uid(),at:new Date().toISOString(),answers:[...quizAnswers],correct:quizAnswers.reduce((n,a,i)=>n+(a===questions[i].correct?1:0),0),hints:quizHints.filter(Boolean).length};P().attempts.push(a);P().resume=null;persist('Đã ghi nhận lượt kiểm tra mẫu trên trình duyệt này.');quizFinished=true;go('summary');}break;
case 'restartquiz':resetQuiz();go('quiz');break;
case 'savesummary':{const a=P().attempts.at(-1);if(a)addNote({type:'summary',title:'Tổng kết bài mẫu · Giới thiệu bản thân',body:a.correct+'/3 câu đúng; '+a.hints+' câu dùng gợi ý.\nBước tiếp theo: '+(a.correct<3?'xem lại câu cần ôn, rồi thử đặt câu của riêng mình.':'thử dùng mẫu câu trong tình huống mới.'),source:'Hệ thống tổng hợp từ lượt kiểm tra mẫu',target:'mistakes',dedupe:'summary-'+a.id});break;}
case 'savemistake':{const i=Number(b.dataset.index),q=questions[i];addNote({type:'mistake',title:q.q,body:q.explanation,source:'Lỗi trong bài kiểm tra mẫu',target:'quiz',dedupe:'mistake-'+i});break;}
case 'kanaset':kanaSet=b.dataset.set;kana=(kanaSet==='hira'?hira:kata)[25];strokeHistory=[];drawingSaved=false;render(false);break;
case 'kanachar':kana=b.dataset.char;strokeHistory=[];drawingSaved=false;render(false);break;
case 'writemode':writeMode=b.dataset.mode;render(false);break;
case 'writingundo':strokeHistory.pop();drawingSaved=false;redraw();break;
case 'writingclear':strokeHistory=[];currentStroke=[];drawingSaved=false;redraw();break;
case 'writingguide':showGlyph=!showGlyph;render(false);break;
case 'savewriting':if(!strokeHistory.length)toast('Hãy viết thử trước khi lưu lượt luyện.');else if(drawingSaved)toast('Lượt này đã lưu. Viết thêm hoặc xóa để bắt đầu lượt khác.');else{P().writing++;drawingSaved=true;persist('Đã lưu lượt tự luyện; chưa chấm độ đúng của nét.');}break;
case 'flipflash':flashFlipped=!flashFlipped;render(false);break;
case 'nextflash':flashIndex=(flashIndex+1)%words.length;flashFlipped=false;render(false);break;
case 'rateflash':if(!flashFlipped)break;P().flashReviews.push({wordId:words[flashIndex].id,rating:b.dataset.rating,at:new Date().toISOString()});persist('Đã ghi tự đánh giá, chưa coi là kết quả kiểm tra trí nhớ.');flashIndex=(flashIndex+1)%words.length;flashFlipped=false;render(false);break;
case 'saveflash':case 'saveword':{const w=b.dataset.action==='saveflash'?words[flashIndex]:words.find(w=>w.id===id);if(w)addNote({type:'word',title:w.word+' · '+w.reading,body:w.meaning+'\n'+w.example,source:'Bộ từ minh họa · '+w.id,target:'dictionary',dedupe:'word-'+w.id});break;}
case 'newnote':editorNote();break;case 'editnote':editorNote(id);break;
case 'deletenote':modal('Xóa mục trong bản thử?',`<p>Chỉ xóa mục này của hồ sơ ${esc(P().name)} trên trình duyệt đang mở.</p><div class="actions">${button('Xóa mục','confirmdeletenote','btn danger',`data-id="${esc(id)}"`)}<button type="button" class="btn" data-close>Giữ lại</button></div>`);break;
case 'confirmdeletenote':P().notes=P().notes.filter(n=>n.id!==id);persist('Đã xóa mục trong bản thử.');closeModal();render(false);break;
case 'exportprofile':exportProfile();break;
case 'cancelsettings':settingsDirty=false;render(false);break;
case 'staysettings':closeModal();break;
case 'discardsettings':settingsDirty=false;go(pendingRoute);break;
case 'archiveprofile':if(P().role!=='manager'||id===P().id)break;modal('Lưu trữ hồ sơ mẫu?',`<p>Hồ sơ sẽ được ẩn khỏi danh sách chọn. Ghi chú và kết quả thử vẫn được giữ để khôi phục.</p><div class="actions">${button('Lưu trữ hồ sơ','confirmarchive','btn primary',`data-id="${esc(id)}"`)}<button type="button" class="btn" data-close>Hủy</button></div>`);break;
case 'confirmarchive':if(P().role==='manager'&&id!==P().id){const p=db.profiles.find(p=>p.id===id);if(p)p.archived=true;persist('Đã lưu trữ hồ sơ thử.');closeModal();render(false);}break;
case 'restoreprofile':if(P().role==='manager'){const p=db.profiles.find(p=>p.id===id);if(p)p.archived=false;persist('Đã khôi phục hồ sơ mẫu.');render(false);}break;
case 'resetprofile':modal('Đặt lại hoạt động thử?',`<p>Sẽ xóa phiên học, lịch ôn, ghi chú, kết quả kiểm tra, lượt thẻ và lượt viết của <strong>${esc(P().name)}</strong>. Tên và mục tiêu được giữ.</p><div class="actions">${button('Xóa hoạt động thử','confirmresetprofile','btn danger')}<button type="button" class="btn" data-close>Hủy</button></div>`);break;
case 'confirmresetprofile':if(window.NPLessonUI)NPLessonUI.clear(P().id);Object.assign(P(),{notes:[],attempts:[],flashReviews:[],writing:0,resume:null,practiceResults:[],activePractice:null,examSessions:{},examAttempts:[]});resetLearningView();persist('Đã đặt lại hoạt động thử của hồ sơ hiện tại.');closeModal();render(false);break;
case 'resetdemo':modal('Đặt lại hồ sơ và hoạt động học thử?',`<p>Khôi phục bốn hồ sơ mẫu ban đầu. Các hồ sơ thêm, ghi chú và cấu hình học thử sẽ bị xóa. Bản nháp nội dung được quản lý riêng trong Xưởng nội dung. Không tác động dữ liệu của ứng dụng khác.</p><div class="actions">${button('Đặt lại bản thử','confirmresetdemo','btn danger')}<button type="button" class="btn" data-close>Hủy</button></div>`);break;
case 'confirmresetdemo':if(window.NPLessonUI)NPLessonUI.clearAll();db={schemaVersion:1,current:'demo-a',profiles:structuredClone(initialProfiles)};settingsDirty=false;resetLearningView();persist('Đã khôi phục bộ hồ sơ mẫu.');closeModal();go('map');break;
}});
document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('[data-form]'))return;e.preventDefault();const data=new FormData(f),p=P();switch(f.dataset.form){case 'demologin':{if(data.get('learner')==='guest'){accessError='';go('guest');break;}const code=String(data.get('demoCode')||'').trim().toUpperCase();const target=db.profiles.find(x=>x.id===data.get('learner')&&!x.archived);if(code!=='PATH-DEMO'||!target){accessError='Mã demo chưa đúng. Dùng PATH-DEMO để thử luồng.';const err=$('#login-error');err.textContent=accessError;err.hidden=false;f.querySelector('[name=demoCode]').setAttribute('aria-invalid','true');Locale.translate(err);f.querySelector('[name=demoCode]').focus();return;}db.current=target.id;rememberDemoProfile=data.has('rememberProfile');db.demoLoginProfile=rememberDemoProfile?target.id:null;accessError='';resetLearningView();persist();go(target.onboarded?'today':'onboarding');break;}case 'recover':recoverTargetId=String(data.get('learner'));go('recovery');break;case 'reset-access':{const a=String(data.get('samplePassword')||''),b=String(data.get('sampleConfirm')||'');if(a.length<8||a!==b){resetError='Hai giá trị mẫu cần giống nhau và có ít nhất 8 ký tự.';const err=$('#reset-error');err.textContent=resetError;err.hidden=false;Locale.translate(err);return;}resetError='';f.reset();go('reset-done');break;}case 'invite':{const code=String(data.get('inviteCode')||'').trim().toUpperCase();if(code!=='PATH-FAMILY'){inviteError='Mã mẫu chưa đúng. Dùng PATH-FAMILY để xem luồng.';const err=$('#invite-error');err.textContent=inviteError;err.hidden=false;Locale.translate(err);return;}inviteError='';go('invite-preview');break;}case 'join':{const name=String(data.get('name')||'').trim();if(!name)return;const n=structuredClone(initialProfiles[0]);Object.assign(n,{id:uid(),name,goal:'Nền tảng',minutes:15,role:'learner',color:Number(data.get('color')),onboarded:false});db.profiles.push(n);db.current=n.id;resetLearningView();if(persist('Đã tạo hồ sơ thử trên trình duyệt này.'))go('onboarding');break;}case 'onboarding':p.name=String(data.get('name')).trim();p.goal=String(data.get('goal'));p.minutes=Number(data.get('minutes'));p.onboarded=true;if(persist('Đã lưu thiết lập thử.'))go('ready');break;
case 'addprofile':if(p.role!=='manager')return;{const n=structuredClone(initialProfiles[0]);Object.assign(n,{id:uid(),name:String(data.get('name')).trim(),goal:String(data.get('goal')),minutes:Number(data.get('minutes')),role:'learner',color:db.profiles.length%4,onboarded:false});if(!n.name)return;db.profiles.push(n);if(persist('Đã thêm hồ sơ thử. Chưa tạo tài khoản đăng nhập.')){closeModal();render(false);}}break;
case 'shortcuts':{const selected=data.getAll('shortcuts');if(selected.length>3){toast('Chọn tối đa ba lối tắt.');return;}p.shortcuts=selected;if(persist('Đã lưu lối tắt của hồ sơ này.')){closeModal();render(false);}}break;
case 'note':{const id=f.dataset.id,old=p.notes.find(n=>n.id===id),n={id:old?.id||uid(),type:String(data.get('type')),title:String(data.get('title')).trim(),body:String(data.get('body')).trim(),source:String(data.get('source')).trim()||'Học viên tự viết',target:old?.target||'',dedupe:old?.dedupe||'',at:old?.at||new Date().toISOString()};if(!n.title||!n.body)return;if(old)Object.assign(old,n);else p.notes.unshift(n);if(persist('Đã lưu mục sổ học tập trên trình duyệt này.')){closeModal();render(false);}}break;
case 'settings':{const group=f.dataset.group;if(group==='profile'){const name=String(data.get('name')).trim();if(!name)return;p.name=name;p.color=Number(data.get('color'));p.preferredName=String(data.get('preferredName')).trim();}else if(group==='goals'){p.goal=String(data.get('goal'));p.purpose=String(data.get('purpose'));p.course=String(data.get('course'));p.minutes=Number(data.get('minutes'));p.days=data.getAll('days');p.deadline=String(data.get('deadline'));delete p.todayMinutes;}else if(group==='learning'){p.prefs.studyPriority=NPAdvicePolicy.normalize(String(data.get('studyPriority')));p.prefs.furigana=String(data.get('furigana'));p.prefs.romaji=data.has('romaji');}else if(group==='display'){p.prefs.theme=String(data.get('theme'));p.prefs.jpSize=Number(data.get('jpSize'));p.prefs.focus=data.has('focus');p.prefs.motion=data.has('motion');}else if(group==='reminders'){p.prefs.reminders=data.has('reminders');for(const k of ['remindTime','quietStart','quietEnd'])p.prefs[k]=String(data.get(k));}if(persist(group==='reminders'?'Đã lưu lựa chọn thử; chưa có thông báo được gửi.':'Đã lưu cấu hình của hồ sơ trên trình duyệt này.')){settingsDirty=false;render(false);}}break;
}});
document.addEventListener('input',e=>{const el=e.target;if(el.closest('[data-form=settings]'))settingsDirty=true;if(el.id==='note-search'){noteQuery=el.value;$('#note-list').innerHTML=noteList();}else if(el.id==='dictionary-search'){dictionaryQuery=el.value;$('#dictionary-results').innerHTML=dictionaryRows();}else if(el.id==='library-search'){libraryQuery=el.value;$('#library-results').innerHTML=libraryCards();}else if(el.id==='character-search'){characterQuery=el.value;$('#character-results').innerHTML=characterCards();}});
document.addEventListener('change',e=>{if(e.target.id==='note-filter'){noteFilter=e.target.value;$('#note-list').innerHTML=noteList();}if(e.target.matches('.settings-select')){const next='settings/'+e.target.value;if(settingsDirty){e.target.value=route().split('/')[1];pendingRoute=next;modal('Bạn có thay đổi chưa lưu',`<p>Lưu hoặc hủy thay đổi trước khi chuyển nhóm.</p><div class="actions">${button('Tiếp tục chỉnh','staysettings','btn primary')}${button('Bỏ thay đổi & đi tiếp','discardsettings','btn')}</div>`);}else go(next);}});
document.addEventListener('click',e=>{const d=e.target.closest('[data-device]');if(d){device=d.dataset.device;applyDevice();}const ruby=e.target.closest('ruby');if(ruby&&P().prefs.furigana==='tap')ruby.classList.toggle('show-rt');});
window.addEventListener('hashchange',()=>{settingsDirty=false;render();});
window.addEventListener('resize',applyDevice);
window.addEventListener('beforeunload',e=>{if(settingsDirty){e.preventDefault();e.returnValue='';}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
render();
